import { nanoid } from "nanoid";
import bcrypt from "bcryptjs";
import { User } from "@prisma/client";
import { getPrisma } from "@poker-champ/db";
import { logger } from "../../lib/logger.js";

type AuthToken = string;
const DEFAULT_SESSION_TTL_DAYS = 14;
const MIN_USERNAME_LEN = 3;
const MAX_USERNAME_LEN = 24;
const STARTING_BANKROLL_CENTS = 1_000_000;

export class AuthService {
  static async register(
    email: string,
    password: string,
    displayName: string,
    usernameInput?: string,
  ): Promise<{ token: AuthToken; user: User }> {
    const prisma = getPrisma();

    const normalizedEmail = this.normalizeEmail(email);
    const existing = await prisma.user.findUnique({ where: { email: normalizedEmail } });
    if (existing) {
      throw new Error("Email already registered");
    }

    const handle = await this.allocateUsername(normalizedEmail, usernameInput);
    const passwordHash = await bcrypt.hash(password, 12);

    const user = await prisma.user.create({
      data: {
        email: normalizedEmail,
        username: handle.username,
        usernameNormalized: handle.usernameNormalized,
        passwordHash,
        displayName,
        role: "USER",
        bankrollCents: STARTING_BANKROLL_CENTS,
      },
    });

    const token = await this.createSession(user.id);
    return { token, user };
  }

  static async login(email: string, password: string): Promise<{ token: AuthToken; user: User }> {
    const prisma = getPrisma();
    const normalizedEmail = this.normalizeEmail(email);

    const user = await prisma.user.findUnique({ where: { email: normalizedEmail } });
    if (!user) {
      throw new Error("Invalid credentials");
    }

    if (user.isBanned || user.deletedAt) {
      throw new Error("Account is suspended");
    }

    const isValid = await bcrypt.compare(password, user.passwordHash);
    if (!isValid) {
      throw new Error("Invalid credentials");
    }

    const hydrated = await this.ensureUserHandle(user);
    await this.revokeUserSessions(hydrated.id);
    const token = await this.createSession(user.id);
    return { token, user: hydrated };
  }

  static async validateSession(token: string): Promise<User | null> {
    const prisma = getPrisma();
    try {
      const session = await prisma.userSession.findUnique({
        where: { id: token },
        include: { user: true },
      });

      if (!session) return null;

      if (session.expiresAt < new Date()) {
        await prisma.userSession.delete({ where: { id: token } });
        return null;
      }

      if (session.user.isBanned || session.user.deletedAt) return null;

      const now = new Date();
      await prisma.userSession.update({
        where: { id: token },
        data: {
          lastUsedAt: now,
          expiresAt: new Date(now.getTime() + this.getSessionTtlMs()),
        },
      });

      return this.ensureUserHandle(session.user);
    } catch (err: any) {
      logger.error({ err }, "validateSession failed due to backend error");
      const backendErr = new Error("Auth backend unavailable");
      (backendErr as any).code = "AUTH_BACKEND_UNAVAILABLE";
      throw backendErr;
    }
  }

  static async revokeSession(token: string): Promise<void> {
    const prisma = getPrisma();
    await prisma.userSession.deleteMany({ where: { id: token } });
  }

  static async revokeUserSessions(userId: string): Promise<void> {
    const prisma = getPrisma();
    await prisma.userSession.deleteMany({ where: { userId } });
  }

  private static async createSession(userId: string): Promise<string> {
    const prisma = getPrisma();
    const token = nanoid(32);
    const now = new Date();
    const expiresAt = new Date(now.getTime() + this.getSessionTtlMs());

    await prisma.userSession.create({
      data: {
        id: token,
        userId,
        createdAt: now,
        lastUsedAt: now,
        expiresAt,
      },
    });

    return token;
  }

  private static normalizeEmail(email: string) {
    return email.trim().toLowerCase();
  }

  private static normalizeUsername(raw: string): string {
    const cleaned = raw
      .trim()
      .replace(/\s+/g, "_")
      .replace(/[^A-Za-z0-9_]/g, "")
      .toLowerCase();
    return cleaned.slice(0, MAX_USERNAME_LEN);
  }

  private static fallbackUsernameFromEmail(email: string): string {
    const prefix = email.split("@")[0] ?? "player";
    const normalized = this.normalizeUsername(prefix);
    if (normalized.length >= MIN_USERNAME_LEN) return normalized;
    return "player";
  }

  private static async allocateUsername(email: string, usernameInput?: string) {
    const prisma = getPrisma();
    const requested = typeof usernameInput === "string" ? this.normalizeUsername(usernameInput) : "";
    const base = requested || this.fallbackUsernameFromEmail(email);

    if (requested) {
      if (requested.length < MIN_USERNAME_LEN) {
        throw new Error(`Username must be at least ${MIN_USERNAME_LEN} characters`);
      }
      const existing = await prisma.user.findFirst({ where: { usernameNormalized: requested } });
      if (existing) {
        throw new Error("Username already taken");
      }
      return { username: requested, usernameNormalized: requested };
    }

    for (let attempt = 0; attempt < 50; attempt++) {
      const suffix = attempt === 0 ? "" : `_${nanoid(4).toLowerCase()}`;
      const candidate = `${base}${suffix}`.slice(0, MAX_USERNAME_LEN);
      const normalized = this.normalizeUsername(candidate);
      if (normalized.length < MIN_USERNAME_LEN) continue;

      const existing = await prisma.user.findFirst({ where: { usernameNormalized: normalized } });
      if (!existing) {
        return { username: normalized, usernameNormalized: normalized };
      }
    }

    throw new Error("Could not allocate username");
  }

  private static async ensureUserHandle(user: User): Promise<User> {
    if (user.username && user.usernameNormalized) return user;

    const prisma = getPrisma();
    const handle = await this.allocateUsername(user.email, user.username ?? undefined);
    return prisma.user.update({
      where: { id: user.id },
      data: {
        username: handle.username,
        usernameNormalized: handle.usernameNormalized,
      },
    });
  }

  private static getSessionTtlMs() {
    const parsed = Number.parseInt(process.env.SESSION_TTL_DAYS ?? "", 10);
    const days = Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_SESSION_TTL_DAYS;
    return days * 24 * 60 * 60 * 1000;
  }
}

import type { User } from "@prisma/client";

export type PublicUser = Omit<User, "passwordHash">;

export function toPublicUser(user: User): PublicUser {
  const { passwordHash: _passwordHash, ...publicUser } = user;
  return publicUser;
}

import type { NextFunction, Request, Response } from "express";
import { AuthService } from "./AuthService.js";

function parseBearerToken(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  const token = authHeader.slice("Bearer ".length).trim();
  return token.length > 0 ? token : null;
}

export async function requireAuth(req: Request, res: Response, next: NextFunction) {
  try {
    const token = parseBearerToken(req);
    if (!token) {
      res.status(401).json({ error: "Missing or invalid Authorization header" });
      return;
    }

    const user = await AuthService.validateSession(token);
    if (!user) {
      res.status(401).json({ error: "Invalid or expired session" });
      return;
    }

    req.user = user;
    next();
  } catch (err: any) {
    if (err?.code === "AUTH_BACKEND_UNAVAILABLE") {
      res.status(503).json({ error: "Auth service unavailable", code: "AUTH_BACKEND_UNAVAILABLE" });
      return;
    }
    res.status(500).json({ error: "Internal Server Error" });
  }
}

import type { ActionPayload } from "@poker-champ/realtime-contract";
import { logger } from "../../../../lib/logger.js";
import type { BotActionContext, BotBrain } from "../../BotBrain.js";
import type { TightAggressiveCompiledConfig } from "./types.js";
import { deriveFeatures } from "./classifiers/deriveFeatures.js";
import { resolvePreflopNode } from "./lookup/resolvePreflopNode.js";
import { resolvePostflopNode } from "./lookup/resolvePostflopNode.js";
import { resolveActionWeights } from "./transforms/resolveActionWeights.js";
import { applyAxes, type AxisTraceEntry } from "./transforms/applyAxes.js";
import { resolveSizingRecipe, resolveWagerAmount } from "./transforms/resolveSizingRecipe.js";
import { weightedPick } from "./transforms/weightedPick.js";

const WAGER_ACTIONS = new Set<ActionPayload["action"]>(["BET", "RAISE"]);
type DecisionWeights = Partial<Record<ActionPayload["action"], number>>;
type BotDecisionTrace = {
  brainId: "tight_aggressive_v1";
  nodeId: string;
  baseWeights: DecisionWeights;
  axesApplied: AxisTraceEntry[];
  finalWeights: DecisionWeights;
  chosenAction: ActionPayload["action"];
  chosenSizingRecipe?: string;
};

export class TightAggressiveBrain implements BotBrain {
  constructor(private readonly compiled: TightAggressiveCompiledConfig) {}

  pickAction(ctx: BotActionContext): ActionPayload {
    const features = deriveFeatures(ctx, this.compiled.preflop.handTierByComboIndex);
    let nodeId = "unknown";
    let sizingWeights;
    let actionWeights: Partial<Record<ActionPayload["action"], number>>;
    let axesApplied: AxisTraceEntry[] = [];
    let baseWeights: DecisionWeights | undefined;
    if (features.street === "PREFLOP") {
      const preflopNode = resolvePreflopNode(this.compiled.preflop, features);
      nodeId = preflopNode.id;
      sizingWeights = preflopNode.sizingWeights;
      baseWeights = resolveActionWeights(preflopNode, features, ctx.heroActionOptions);
      const axesResult = applyAxes(baseWeights, this.compiled.axes, features);
      axesApplied = axesResult.axesApplied;
      actionWeights = axesResult.weights;
    } else {
      const postflopNode = resolvePostflopNode(this.compiled.postflop, features);
      nodeId = postflopNode.id;
      sizingWeights = postflopNode.sizingWeights;
      baseWeights = resolveActionWeights(postflopNode, features, ctx.heroActionOptions);
      const axesResult = applyAxes(baseWeights, this.compiled.axes, features);
      axesApplied = axesResult.axesApplied;
      actionWeights = axesResult.weights;
    }
    if (!baseWeights) baseWeights = { ...actionWeights };

    const action = weightedPick(actionWeights, ctx.rng) ?? "FOLD";
    let chosenSizingRecipe: string | undefined;

    if (WAGER_ACTIONS.has(action)) {
      const recipe = resolveSizingRecipe(sizingWeights, ctx.rng);
      chosenSizingRecipe = recipe;
      const amountCents = resolveWagerAmount(recipe, ctx, ctx.heroActionOptions);
      emitDecisionTraceIfEnabled(this.compiled, {
        brainId: "tight_aggressive_v1",
        nodeId,
        baseWeights,
        axesApplied,
        finalWeights: actionWeights,
        chosenAction: action,
        chosenSizingRecipe,
      });
      if (amountCents != null) return { action, amountCents };
      return { action };
    }
    emitDecisionTraceIfEnabled(this.compiled, {
      brainId: "tight_aggressive_v1",
      nodeId,
      baseWeights,
      axesApplied,
      finalWeights: actionWeights,
      chosenAction: action,
    });

    return { action };
  }
}

function emitDecisionTraceIfEnabled(config: TightAggressiveCompiledConfig, trace: BotDecisionTrace): void {
  if (!config.debug?.emitDecisionTrace) return;
  logger.debug({ trace }, "BOT_DECISION_TRACE");
}

import type {
  ActionWeights,
  AxisDefinitionAuthoring,
  AxisDefinitionCompiled,
  AxisMeta,
  AxisTier,
  BetSizeBucket,
  ComboWeights169,
  HandTier,
  HandTierByComboIndex,
  PositionBucket,
  PostflopHandClass,
  PostflopNodeAuthoring,
  PostflopNodeCompiled,
  PostflopWeightsTableAuthoring,
  PostflopWeightsTableCompiled,
  PreflopNodeAuthoring,
  PreflopNodeCompiled,
  PreflopWeightsTableAuthoring,
  PreflopWeightsTableCompiled,
  PressureBucket,
  TightAggressiveCompiledConfig,
  TightAggressiveConfigV1,
} from "../types.js";

const PRE_FLOP_COMBO_COUNT = 169;

const POSITION_BUCKETS: readonly PositionBucket[] = ["EARLY", "MIDDLE", "LATE", "BLINDS"];
const PRESSURE_BUCKETS: readonly PressureBucket[] = ["UNOPENED", "VS_RAISE", "VS_3BET_PLUS", "VS_ALLIN"];
const FACING_BET_SIZE_BUCKETS: readonly Exclude<BetSizeBucket, "NONE">[] = ["SMALL", "MEDIUM", "LARGE", "MAX"];
const POSTFLOP_STREETS = ["FLOP", "TURN", "RIVER"] as const;
const POSTFLOP_HAND_CLASSES: readonly PostflopHandClass[] = ["AIR", "WEAK_MADE", "STRONG_MADE"];
const HAND_TIERS: readonly HandTier[] = ["PREMIUM", "STRONG", "GOOD", "SPEC", "TRASH"];
const AXIS_FEATURES = [
  "playerCountBucket",
  "potOddsBucket",
  "drawBucket",
  "positionPostflopBucket",
  "stackBucket",
  "facingPressureBucket",
  "initiativeBucket",
  "streetBucket",
  "initiativeStreetCountBucket",
  "sprBucket",
  "boardPairedBucket",
  "boardWetnessBucket",
  "boardMonotoneBucket",
  "straightConnectivityBucket",
  "hasOverpairBucket",
  "topPairKickerStrengthBucket",
  "madeHandStrengthBucket",
  "blockerStrengthBucket",
  "opponentTightnessBucket",
  "opponentAggressionBucket",
  "recentAggressionHistoryBucket",
  "tableImageBucket",
  "betSizeRelativeToStackBucket",
  "callCostRelativeToStackBucket",
  "tournamentIcmPressureBucket",
  "multiwayEquityPenaltyBucket",
  "riskToleranceBucket",
  "tiltLevelBucket",
  "timePressureBucket",
  "openOpportunityBucket",
  "squeezeOpportunityBucket",
  "limpPresentBucket",
] as const;

export function loadTightAggressiveConfig(config: unknown): TightAggressiveCompiledConfig {
  const c = validateTopLevel(config);
  const nodeIds = new Set<string>();

  validateHandTierMap(c.preflop.handTierByComboIndex);
  const compiledPreflop = compilePreflopTable(c.preflop.table, c.preflop.handTierByComboIndex, nodeIds);
  const compiledPostflop = compilePostflopTable(c.postflop.table, nodeIds);
  const compiledAxes = compileAxes(c.axes ?? []);
  const compiledAxisMeta = compileAxisMeta(c.axisMeta ?? [], compiledAxes);

  const compiled: TightAggressiveCompiledConfig = {
    version: 1,
    metadata: { ...c.metadata },
    normalization: { ...c.normalization },
    preflop: {
      comboIndexMap: c.preflop.comboIndexMap,
      handTierByComboIndex: [...c.preflop.handTierByComboIndex] as HandTierByComboIndex,
      table: compiledPreflop,
    },
    postflop: {
      evaluator: c.postflop.evaluator,
      table: compiledPostflop,
    },
    axes: compiledAxes,
    axisMeta: compiledAxisMeta,
    sizing: { ...c.sizing },
    safety: { ...c.safety },
    debug: c.debug ? { ...c.debug } : undefined,
  };

  return deepFreeze(compiled);
}

function validateTopLevel(config: unknown): TightAggressiveConfigV1 {
  if (!config || typeof config !== "object") {
    throw new Error("TIGHT_AGGRESSIVE_CONFIG_INVALID: expected object");
  }
  const c = config as TightAggressiveConfigV1;
  if (c.version !== 1) {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_VERSION: expected 1, received ${String((c as any).version)}`);
  }
  if (!c.metadata?.id || !c.metadata?.label) {
    throw new Error("TIGHT_AGGRESSIVE_CONFIG_INVALID_METADATA");
  }
  if (!c.preflop?.table || !c.postflop?.table) {
    throw new Error("TIGHT_AGGRESSIVE_CONFIG_INVALID_TABLES");
  }
  return c;
}

function compilePreflopTable(
  table: PreflopWeightsTableAuthoring,
  handTierByComboIndex: HandTierByComboIndex,
  nodeIds: Set<string>,
): PreflopWeightsTableCompiled {
  const compiled = {} as PreflopWeightsTableCompiled;
  for (const pos of POSITION_BUCKETS) {
    const posEntry = table[pos];
    if (!posEntry) throw new Error(`TIGHT_AGGRESSIVE_CONFIG_MISSING_POSITION: ${pos}`);

    compiled[pos] = {
      UNOPENED: compilePreflopNode(posEntry.UNOPENED, handTierByComboIndex, nodeIds, `${pos}.UNOPENED`),
      VS_RAISE: compileFacingMap(posEntry.VS_RAISE, handTierByComboIndex, nodeIds, `${pos}.VS_RAISE`),
      VS_3BET_PLUS: compileFacingMap(posEntry.VS_3BET_PLUS, handTierByComboIndex, nodeIds, `${pos}.VS_3BET_PLUS`),
      VS_ALLIN: compileFacingMap(posEntry.VS_ALLIN, handTierByComboIndex, nodeIds, `${pos}.VS_ALLIN`),
    };
  }
  return compiled;
}

function compileFacingMap(
  facingMap: Record<Exclude<BetSizeBucket, "NONE">, PreflopNodeAuthoring>,
  handTierByComboIndex: HandTierByComboIndex,
  nodeIds: Set<string>,
  path: string,
): Record<Exclude<BetSizeBucket, "NONE">, PreflopNodeCompiled> {
  const compiled = {} as Record<Exclude<BetSizeBucket, "NONE">, PreflopNodeCompiled>;
  for (const size of FACING_BET_SIZE_BUCKETS) {
    const node = facingMap[size];
    if (!node) throw new Error(`TIGHT_AGGRESSIVE_CONFIG_MISSING_BET_SIZE_NODE: ${path}.${size}`);
    compiled[size] = compilePreflopNode(node, handTierByComboIndex, nodeIds, `${path}.${size}`);
  }
  return compiled;
}

function compilePreflopNode(
  node: PreflopNodeAuthoring,
  handTierByComboIndex: HandTierByComboIndex,
  nodeIds: Set<string>,
  path: string,
): PreflopNodeCompiled {
  validateNodeId(node.id, nodeIds, path);
  validateNonNegativeWeightMap(node.actionWeights, `${path}.actionWeights`);
  if (node.sizingWeights) validateNonNegativeWeightMap(node.sizingWeights, `${path}.sizingWeights`);

  const hasRaw = Array.isArray(node.comboWeights169);
  const hasTier = !!node.comboTierWeights;
  if (!hasRaw && !hasTier) {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_PRELFLOP_NODE_MISSING_COMBO_WEIGHTS: ${path}`);
  }

  let comboWeights169: ComboWeights169;
  let comboWeightSource: "TIER" | "RAW_169";
  if (hasRaw) {
    comboWeights169 = validateAndNormalizeComboWeights(node.comboWeights169 as number[], `${path}.comboWeights169`);
    comboWeightSource = "RAW_169";
  } else {
    comboWeights169 = compileTierWeightsTo169(node.comboTierWeights!, handTierByComboIndex, `${path}.comboTierWeights`);
    comboWeightSource = "TIER";
  }

  return {
    id: node.id,
    comboWeights169,
    comboWeightSource,
    actionWeights: normalizeWeightMap(node.actionWeights),
    sizingWeights: node.sizingWeights ? normalizeWeightMap(node.sizingWeights) : undefined,
    notes: node.notes,
  };
}

function compilePostflopTable(table: PostflopWeightsTableAuthoring, nodeIds: Set<string>): PostflopWeightsTableCompiled {
  const compiled = {} as PostflopWeightsTableCompiled;
  for (const street of POSTFLOP_STREETS) {
    const streetEntry = table[street];
    if (!streetEntry) throw new Error(`TIGHT_AGGRESSIVE_CONFIG_MISSING_POSTFLOP_STREET: ${street}`);
    compiled[street] = {} as PostflopWeightsTableCompiled[typeof street];

    for (const pressure of PRESSURE_BUCKETS) {
      const pressureEntry = streetEntry[pressure];
      if (!pressureEntry) throw new Error(`TIGHT_AGGRESSIVE_CONFIG_MISSING_POSTFLOP_PRESSURE: ${street}.${pressure}`);
      compiled[street][pressure] = {} as PostflopWeightsTableCompiled[typeof street][typeof pressure];
      for (const handClass of POSTFLOP_HAND_CLASSES) {
        const node = pressureEntry[handClass];
        if (!node) {
          throw new Error(`TIGHT_AGGRESSIVE_CONFIG_MISSING_POSTFLOP_NODE: ${street}.${pressure}.${handClass}`);
        }
        compiled[street][pressure][handClass] = compilePostflopNode(
          node,
          nodeIds,
          `${street}.${pressure}.${handClass}`,
        );
      }
    }
  }
  return compiled;
}

function compilePostflopNode(node: PostflopNodeAuthoring, nodeIds: Set<string>, path: string): PostflopNodeCompiled {
  validateNodeId(node.id, nodeIds, path);
  validateNonNegativeWeightMap(node.actionWeights, `${path}.actionWeights`);
  if (node.sizingWeights) validateNonNegativeWeightMap(node.sizingWeights, `${path}.sizingWeights`);

  return {
    id: node.id,
    actionWeights: normalizeWeightMap(node.actionWeights),
    sizingWeights: node.sizingWeights ? normalizeWeightMap(node.sizingWeights) : undefined,
    notes: node.notes,
  };
}

function compileAxes(axes: AxisDefinitionAuthoring[]): AxisDefinitionCompiled[] {
  const seen = new Set<string>();
  const compiled = axes.map((axis, idx) => {
    if (!axis.id || typeof axis.id !== "string") {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_AXIS_ID: index ${idx}`);
    }
    if (seen.has(axis.id)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_DUPLICATE_AXIS_ID: ${axis.id}`);
    }
    seen.add(axis.id);
    if (!Number.isFinite(axis.order)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_AXIS_ORDER: ${axis.id}`);
    }
    const strength = axis.strength ?? 1;
    if (!Number.isFinite(strength) || strength < 0) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_AXIS_STRENGTH: ${axis.id}`);
    }
    if (!AXIS_FEATURES.includes(axis.feature)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_AXIS_FEATURE: ${axis.id}`);
    }

    const buckets: AxisDefinitionCompiled["buckets"] = {};
    for (const [bucket, mods] of Object.entries(axis.buckets ?? {})) {
      validateNonNegativeWeightMap(mods, `axes.${axis.id}.buckets.${bucket}`);
      buckets[bucket] = normalizeWeightMap(mods);
    }

    return {
      id: axis.id,
      order: axis.order,
      feature: axis.feature,
      strength,
      buckets,
    };
  });

  compiled.sort((a, b) => a.order - b.order || a.id.localeCompare(b.id));
  return compiled;
}

function compileAxisMeta(axisMeta: AxisMeta[], axes: AxisDefinitionCompiled[]): AxisMeta[] {
  const byAxisId = new Map(axes.map((axis) => [axis.id, axis]));
  const byMetaId = new Map<string, AxisMeta>();
  for (const meta of axisMeta) {
    if (!meta.id || !byAxisId.has(meta.id)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_AXIS_META_ID: ${meta.id}`);
    }
    if (byMetaId.has(meta.id)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_DUPLICATE_AXIS_META_ID: ${meta.id}`);
    }
    if (!isAxisTier(meta.tier)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_AXIS_META_TIER: ${meta.id}`);
    }
    byMetaId.set(meta.id, { ...meta });
  }

  for (const axis of axes) {
    const meta = byMetaId.get(axis.id);
    if (!meta) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_MISSING_AXIS_META: ${axis.id}`);
    }
    validateTierInvariant(axis, meta.tier);
  }

  return [...byMetaId.values()].sort((a, b) => a.id.localeCompare(b.id));
}

function validateTierInvariant(axis: AxisDefinitionCompiled, tier: AxisTier): void {
  const hasNonNeutral = axisHasNonNeutralMultiplier(axis.buckets);
  if (tier === "ACTIVE" && !hasNonNeutral) {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_AXIS_TIER_VIOLATION_ACTIVE: ${axis.id}`);
  }
  if ((tier === "NEUTRAL" || tier === "FUTURE") && hasNonNeutral) {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_AXIS_TIER_VIOLATION_${tier}: ${axis.id}`);
  }
}

function axisHasNonNeutralMultiplier(buckets: Record<string, ActionWeights>): boolean {
  for (const modifiers of Object.values(buckets)) {
    for (const value of Object.values(modifiers)) {
      if (value == null) continue;
      if (value !== 1) return true;
    }
  }
  return false;
}

function isAxisTier(value: unknown): value is AxisTier {
  return value === "ACTIVE" || value === "NEUTRAL" || value === "FUTURE";
}

function validateHandTierMap(map: HandTierByComboIndex): void {
  if (!Array.isArray(map) || map.length !== PRE_FLOP_COMBO_COUNT) {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_HAND_TIER_MAP_LENGTH: expected ${PRE_FLOP_COMBO_COUNT}`);
  }
  map.forEach((tier, idx) => {
    if (!HAND_TIERS.includes(tier)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_HAND_TIER_AT_INDEX: ${idx}`);
    }
  });
}

function validateNodeId(id: string, nodeIds: Set<string>, path: string): void {
  if (!id || typeof id !== "string") {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_NODE_ID: ${path}`);
  }
  if (nodeIds.has(id)) {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_DUPLICATE_NODE_ID: ${id}`);
  }
  nodeIds.add(id);
}

function compileTierWeightsTo169(
  comboTierWeights: Partial<Record<HandTier, number>>,
  handTierByComboIndex: HandTierByComboIndex,
  path: string,
): ComboWeights169 {
  validateNonNegativeWeightMap(comboTierWeights, path);
  const compiled = handTierByComboIndex.map((tier) => comboTierWeights[tier] ?? 0);
  return validateAndNormalizeComboWeights(compiled, `${path}.compiled`);
}

function validateAndNormalizeComboWeights(weights: number[], path: string): ComboWeights169 {
  if (!Array.isArray(weights) || weights.length !== PRE_FLOP_COMBO_COUNT) {
    throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_COMBO_WEIGHT_LENGTH: ${path}`);
  }
  weights.forEach((weight, idx) => {
    if (!isFiniteNonNegativeNumber(weight)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_COMBO_WEIGHT_VALUE: ${path}[${idx}]`);
    }
  });
  return [...weights] as ComboWeights169;
}

function validateNonNegativeWeightMap(input: Record<string, number | undefined>, path: string): void {
  Object.entries(input).forEach(([key, value]) => {
    if (value == null) return;
    if (!isFiniteNonNegativeNumber(value)) {
      throw new Error(`TIGHT_AGGRESSIVE_CONFIG_INVALID_WEIGHT: ${path}.${key}`);
    }
  });
}

function normalizeWeightMap<T extends Record<string, number | undefined>>(input: T): T {
  return { ...input };
}

function isFiniteNonNegativeNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

function deepFreeze<T>(input: T): T {
  if (input === null || typeof input !== "object" || Object.isFrozen(input)) {
    return input;
  }
  Object.freeze(input);
  for (const value of Object.values(input as Record<string, unknown>)) {
    deepFreeze(value);
  }
  return input;
}

/**
 * HandLifecycleService - Core Poker Hand Management
 * 
 * PURPOSE:
 * Manages the complete lifecycle of a poker hand from initialization through completion.
 * Handles betting rounds, street transitions, showdowns, and pot distribution.
 * 
 * KEY RESPONSIBILITIES:
 * - Hand initialization and player state management
 * - Street transitions (preflop → flop → turn → river → showdown)
 * - Pot calculation and side pot management
 * - Winner determination and chip distribution
 * - State invariants and financial integrity checks
 * 
 * DETERMINISM:
 * All settlement logic is deterministic - no randomness in payout calculations.
 * Uses seat order for tie-breaking to ensure reproducible results.
 * 
 * USAGE:
 * const service = new HandLifecycleService(dependencies);
 * const plans = await service.startHand();
 * // Execute plans through Dealer execution layer
 */

// ============================================================================
// IMPORTS - External Dependencies
// ============================================================================
import { newId } from "../../../lib/ids.js";
import { logger } from "../../../lib/logger.js";
import pokersolver from "pokersolver";

// ============================================================================
// IMPORTS - Internal Dependencies
// ============================================================================
import { DeckService } from "../../cards/DeckService.js";
import { PokerError } from "../../errors.js";
import type { PersistenceFacade } from "../../persistence/PersistenceFacade.js";
import type { PokerState, Street } from "../../../state/PokerState.js";

// ============================================================================
// IMPORTS - Poker Rules & Game Logic
// ============================================================================
import {
  allRemainingPlayersAllInOrFolded,
  eligibleToAct,
  eligibleForShowdown,
  noFurtherBettingPossible,
  resetBettingRound,
  syncRoundCurrentBetCents,
} from "../../rules/BettingRound.js";
import { buildSidePots, splitPotCents } from "../../rules/SidePotManager.js";

// ============================================================================
// IMPORTS - Services
// ============================================================================
import { SettlementService } from "../settlement/SettlementService.js";

// ============================================================================
// IMPORTS - Utilities & Helpers
// ============================================================================
import {
  countActiveHumanPlayers,
  findNextToActSeat,
  resolveActivePlayersForHand,
  seatOrderLeftOfDealer,
} from "../utils/TableNavigator.js";

// ============================================================================
// IMPORTS - Invariants & Validation
// ============================================================================
import { maybeAssertStateInvariants } from "../../invariants/assertState.js";
import { maybeAssertBettingState } from "../../invariants/assertBettingState.js";
import { assertMoneyConservationTransition } from "../../invariants/assertMoneyConservation.js";
import { shouldFailClosedMoneyPath } from "../../invariants/moneyStrictMode.js";

// ============================================================================
// IMPORTS - Constants & Timing
// ============================================================================
import { HAND_RESULT_HOLD_MS, RUNOUT_STAGE_DELAY_MS } from "../timing.js";

// ============================================================================
// IMPORTS - Type Definitions
// ============================================================================
import type { SnapshotReason } from "./SnapshotService.js";
import type { TableSnapshotPayload } from "@poker-champ/realtime-contract";

// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

/**
 * Poker solver type definition for hand evaluation
 */
const { Hand } = pokersolver as {
  Hand: {
    solve(cards: string[]): unknown;
    winners(hands: unknown[]): unknown[];
  };
};

/**
 * Result type for solved poker hand
 */
type SolvedHand = { descr?: string; name?: string };

/**
 * Plan types for hand lifecycle execution
 * Each plan represents an atomic operation that can be executed by the Dealer
 */
export type HandLifecyclePlan =
  | { kind: "EMIT_SNAPSHOT"; reason: SnapshotReason; actionId?: string }
  | { kind: "DELAY"; ms: number }
  | { kind: "MAYBE_AUTOMATE_TURN" }
  | { kind: "TRANSITION_TO_WAITING" }
  | { kind: "RELEASE_PENDING_SEATS" }
  | { kind: "SCHEDULE_NEXT_HAND"; reason: string; delayMs?: number }
  | { kind: "HAND_ENDED"; reason: "LAST_PLAYER" | "SHOWDOWN" | "DEFENSIVE_FALLBACK"; outcome: { potCents: number; winnerId?: string; payoutsByUserId: Record<string, number> } };

// ============================================================================
// MAIN CLASS - Hand Lifecycle Management
// ============================================================================

/**
 * HandLifecycleService - Core service for managing poker hand lifecycle
 * 
 * This class orchestrates the complete flow of a poker hand from start to finish.
 * It maintains deterministic behavior for fair gameplay and provides comprehensive
 * error handling and state validation.
 */
export class HandLifecycleService {
  // ============================================================================
  // CLASS PROPERTIES
  // ============================================================================
  
  /** Lifetime: one hand. Set in startHand after we have 2+ active players; cleared at start of startHand. */
  private deck: DeckService | null = null;
  /** Set in startHand when we have 2+ active players; reset at start of startHand. Meaningful only after a successful hand start. */
  private currentHandIncludesBotParticipants = false;
  /** Players dealt into the current hand. Only these players may have needsAction=true during this hand. */
  private currentHandInHandIds = new Set<string>();

  // ============================================================================
  // CONSTRUCTOR & DEPENDENCIES
  // ============================================================================
  
  /**
   * Initialize HandLifecycleService with required dependencies
   * @param deps - Service dependencies for state, persistence, and settlement
   */
  constructor(private readonly deps: {
    state: PokerState;
    persistence: PersistenceFacade;
    settlementService: SettlementService;
    getHoleCardsByPlayerId: () => Map<string, string[]>;
    getHandStartingStacksByPlayerId: () => Map<string, number>;
    currentHandAutoActedUserIds: Set<string>;
    /** Hand-setup only: clear at hand start. Action dedup (check/record) lives in Dealer/HandContext. */
    getProcessedActionIds: () => Set<string>;
    applyDisconnectedAutoActionCapForHand: () => Promise<void>;
    setLastHandResult: (value: TableSnapshotPayload["lastHandResult"] | undefined) => void;
    setLastAction: (value: TableSnapshotPayload["lastAction"] | undefined) => void;
  }) {}

  // ============================================================================
  // UTILITY METHODS
  // ============================================================================

  /**
   * Calculate total chips across all players
   * @returns Sum of all player stack sizes
   */
  private sumStacksCents(): number {
    let sum = 0;
    for (const p of this.deps.state.playersById.values()) {
      if (p) {
        sum += p.stackCents;
      }
    }
    return sum;
  }

  private getHoleCardsByPlayerIdSafe(): Map<string, string[]> {
    if (typeof this.deps.getHoleCardsByPlayerId === "function") {
      return this.deps.getHoleCardsByPlayerId();
    }
    return new Map<string, string[]>();
  }

  private getHandStartingStacksByPlayerIdSafe(): Map<string, number> {
    if (typeof this.deps.getHandStartingStacksByPlayerId === "function") {
      return this.deps.getHandStartingStacksByPlayerId();
    }
    return new Map<string, number>();
  }

  private getProcessedActionIdsSafe(): Set<string> {
    if (typeof this.deps.getProcessedActionIds === "function") {
      return this.deps.getProcessedActionIds();
    }
    return new Set<string>();
  }

  /**
   * Apply hand-scoped needsAction flags for the current street.
   * Only players dealt into this hand can be actionable.
   */
  private applyNeedsActionForCurrentHand(): void {
    const { state } = this.deps;
    for (const player of state.playersById.values()) {
      player.needsAction = this.currentHandInHandIds.has(player.id) && eligibleToAct(player);
    }
  }

  private assertHandResultPayoutsOrThrow(
    payoutsByUserId: Record<string, number>,
    potCents: number,
    context: string,
  ): void {
    const payoutSum = Object.values(payoutsByUserId).reduce((sum, amount) => sum + amount, 0);
    if (payoutSum !== potCents) {
      throw new PokerError(
        "BAD_STATE",
        `${context}: HAND_RESULT_PAYOUTS_MUST_EQUAL_POT (payouts=${payoutSum}, pot=${potCents}, hand=${this.deps.state.handId}).`,
      );
    }
  }

  private shouldAssertLedgerForCurrentHand(): boolean {
    return !this.currentHandIncludesBotParticipants;
  }

  // ============================================================================
  // CALCULATION & VALIDATION METHODS
  // ============================================================================

  /**
   * Calculate uncalled chips that must be returned to aggressor before final payout.
   *
   * PROCESS:
   * 1. Identify all players who contributed chips (committed > 0)
   * 2. Sort by contribution amount (highest first)
   * 3. Calculate difference between highest and second-highest contributors
   * 4. Only ACTIVE players can have uncalled chips (ALL_IN players commit everything)
   *
   * EXAMPLE:
   * Player A bets 1000, Player B (100 chips) folds
   * → A's 900 is uncalled and must be returned, not paid from pot
   *
   * @param state Current poker state
   * @returns Object with uncalled amount and player ID, or zero if no uncalled chips
   */
  private calculateUncalledCents(state: PokerState): { cents: number; playerId: string | null } {
    // Step 1: Get all contributors sorted by contribution amount
    const contributors = [...state.playersById.values()]
      .filter((p) => p.status !== "OUT" && p.committedCents > 0)
      .map((p) => ({ id: p.id, committed: p.committedCents, status: p.status }))
      .sort((a, b) => b.committed - a.committed);

    // Step 2: Handle trivial case (single contributor)
    if (contributors.length < 2) {
      return { cents: 0, playerId: null };
    }

    // Step 3: Calculate uncalled amount for top contributor
    const top = contributors[0]!;
    const secondHighest = contributors[1]!.committed;

    // Step 4: Only ACTIVE players can have uncalled chips
    if (top.status !== "ACTIVE") {
      return { cents: 0, playerId: null };
    }

    const uncalledCents = top.committed - secondHighest;
    if (uncalledCents <= 0) return { cents: 0, playerId: null };

    return { cents: uncalledCents, playerId: top.id };
  }

  /**
   * Assert chip mass conservation throughout hand lifecycle
   *
   * VALIDATION RULES:
   * 1. Total chip mass must remain constant (stacks + pot - disbursed = initial)
   * 2. If requireFullySettled: pot must be fully disbursed and stacks restored
   *
   * @param state Current poker state
   * @param context Context description for error reporting
   * @param requireFullySettled Whether to enforce full settlement checks
   */
  private assertHandMassOrThrow(state: PokerState, context: string, requireFullySettled = false): void {
    const { settlementService } = this.deps;
    const totalStacksCents = this.sumStacksCents();
    const disbursedCents = settlementService.getCurrentHandPotDisbursedCents();
    const effectiveMassCents = totalStacksCents + state.potCents - disbursedCents;

    // Compatibility fallback for tests that seed an in-progress hand directly
    // without running startHand() (which initializes initialChipMassCents).
    if (state.initialChipMassCents <= 0) {
      state.initialChipMassCents = effectiveMassCents;
    }
    
    // Rule 1: Total chip mass conservation
    if (effectiveMassCents !== state.initialChipMassCents) {
      throw new PokerError(
        "BAD_STATE",
        `${context}: hand chip mass mismatch (initial=${state.initialChipMassCents}, effective=${effectiveMassCents}, stacks=${totalStacksCents}, pot=${state.potCents}, disbursed=${disbursedCents}, hand=${state.handId}).`,
      );
    }
    
    // Rule 2: Full settlement validation (if required)
    if (requireFullySettled) {
      if (disbursedCents !== state.potCents) {
        throw new PokerError(
          "BAD_STATE",
          `${context}: expected pot disbursed to equal pot (pot=${state.potCents}, disbursed=${disbursedCents}, hand=${state.handId}).`,
        );
      }
      if (totalStacksCents !== state.initialChipMassCents) {
        throw new PokerError(
          "BAD_STATE",
          `${context}: ending stack mass mismatch (initial=${state.initialChipMassCents}, stacks=${totalStacksCents}, hand=${state.handId}).`,
        );
      }
    }
  }

  // ============================================================================
  // HAND LIFECYCLE METHODS
  // ============================================================================

  /**
   * Initialize and start a new poker hand
   * 
   * PROCESS:
   * 1. Reset hand state and clear previous data
   * 2. Validate minimum active players
   * 3. Resolve active players and update dealer position
   * 4. Initialize deck and deal hole cards
   * 5. Post blinds and set up first action
   * 6. Generate execution plans for Dealer
   * 
   * @returns Array of lifecycle plans to be executed
   */
  async startHand(): Promise<HandLifecyclePlan[]> {
    const plans: HandLifecyclePlan[] = [];
    const { state } = this.deps;
    this.deck = null;
    this.currentHandIncludesBotParticipants = false;
    this.currentHandInHandIds.clear();
    this.getHandStartingStacksByPlayerIdSafe().clear();
    if (countActiveHumanPlayers(state) === 0) return plans;
    state.runningSinceTs = Date.now();

    const handId = newId("hand");
    state.handId = handId;
    state.handNumber += 1;
    this.deps.currentHandAutoActedUserIds.clear();
    this.deps.settlementService.resetHandCounters();
    this.getProcessedActionIdsSafe().clear();
    state.street = "PREFLOP";
    state.runoutMode = "NONE";
    state.board.clear();
    state.potCents = 0;
    state.handActionSeq = 0;
    state.actionCount = 0;
    state.initialChipMassCents = 0;
    state.nextHandAtTs = 0;
    this.deps.setLastHandResult(undefined);
    this.deps.setLastAction(undefined);

    resetBettingRound(state);

    // Consume one-hand sit-out tokens and reset player states in single pass
    for (const player of state.playersById.values()) {
      player.sittingOutUntilNextHand = false;
      if (player.connected && player.status === "ABANDONED" && player.stackCents > 0) {
        player.status = "ACTIVE";
      }
      player.roundBetCents = 0;
      player.committedCents = 0;
      player.needsAction = false;
      if (player.status !== "OUT" && player.status !== "ABANDONED") {
        player.status = player.stackCents > 0 ? "ACTIVE" : "OUT";
      }
    }

    // Resolve active players for this hand after consuming sit-out-until-next-hand flags.
    const activePlayers = resolveActivePlayersForHand(state);

    if (activePlayers.length < 2) {
      state.street = "WAITING";
      state.runoutMode = "NONE";
      this.currentHandInHandIds.clear();
      plans.push({ kind: "EMIT_SNAPSHOT", reason: "AUTO_TRANSITION" });
      maybeAssertStateInvariants(state);
      return plans;
    }

    state.initialChipMassCents = this.sumStacksCents() + state.potCents;

    const activeSeats = activePlayers
      .map((player) => player.seat)
      .sort((a, b) => a - b);
    const nextSeatFrom = (fromSeat: number): number => {
      const next = activeSeats.find((seat) => seat > fromSeat);
      return next ?? activeSeats[0]!;
    };
    state.dealerSeat = nextSeatFrom(state.dealerSeat);

    this.deck = new DeckService();
    this.deck.shuffle();
    this.currentHandIncludesBotParticipants = activePlayers.some((player) => player.kind === "BOT");
    this.currentHandInHandIds = new Set(activePlayers.map((player) => player.id));

    const startingStacksByUserId = new Map<string, number>();
    for (const player of activePlayers) {
      startingStacksByUserId.set(player.id, player.stackCents);
      this.getHandStartingStacksByPlayerIdSafe().set(player.id, player.stackCents);
    }

    const holeCards = this.getHoleCardsByPlayerIdSafe();
    holeCards.clear();
    for (const player of activePlayers) {
      const cards = [this.drawCard(), this.drawCard()];
      holeCards.set(player.id, cards);
    }

    if (this.deps.persistence.enabled && typeof this.deps.persistence.handHistory?.startHand === "function") {
      await this.deps.persistence.handHistory.startHand({
        tableId: state.tableId,
        handId,
        dealerSeat: state.dealerSeat,
        smallBlindCents: state.smallBlindCents,
        bigBlindCents: state.bigBlindCents,
        players: activePlayers.map((player) => ({
          id: player.id,
          seat: player.seat,
          startingStackCents: startingStacksByUserId.get(player.id) ?? player.stackCents,
          holeCards: holeCards.get(player.id) ?? [],
        })),
      });
    }

    const isHeadsUp = activePlayers.length === 2;
    const sbSeat = isHeadsUp ? state.dealerSeat : nextSeatFrom(state.dealerSeat);
    const bbSeat = nextSeatFrom(sbSeat);
    state.sbSeat = sbSeat;
    state.bbSeat = bbSeat;

    const sbId = state.seats[sbSeat];
    const bbId = state.seats[bbSeat];

    let postedSb = 0;
    let postedBb = 0;

    // Assign handId (state assignment cannot throw)
    state.handId = handId;

    if (sbId) {
      const sb = state.playersById.get(sbId);
      if (!sb) throw new PokerError("BAD_STATE", "Small blind player missing.");
      if (sb.status !== "ACTIVE") {
        logger.error({ handId: state.handId, sbSeat, sbStatus: sb.status }, "SB not ACTIVE at hand start");
        throw new PokerError("BAD_STATE", "Small blind must be ACTIVE at hand start.");
      }
      postedSb = await this.deps.settlementService.postBlind(sb, "SB", state.smallBlindCents);
    }

    if (bbId) {
      const bb = state.playersById.get(bbId);
      if (!bb) throw new PokerError("BAD_STATE", "Big blind player missing.");
      if (bb.status !== "ACTIVE") {
        logger.error({ handId: state.handId, bbSeat, bbStatus: bb.status }, "BB not ACTIVE at hand start");
        throw new PokerError("BAD_STATE", "Big blind must be ACTIVE at hand start.");
      }
      postedBb = await this.deps.settlementService.postBlind(bb, "BB", state.bigBlindCents);
    }

    syncRoundCurrentBetCents(state);
    if (postedBb > 0) {
      state.roundCurrentBetCents = Math.max(state.roundCurrentBetCents, postedBb);
    } else if (postedSb > 0) {
      state.roundCurrentBetCents = Math.max(state.roundCurrentBetCents, postedSb);
    }
    state.minRaiseCents = state.bigBlindCents;
    this.applyNeedsActionForCurrentHand();
    // In heads-up, SB (Dealer) acts first pre-flop, BB acts first on subsequent streets
    // In full ring, BB acts first pre-flop, action proceeds left from BB
    const firstToActSeat = isHeadsUp ? sbSeat : findNextToActSeat(state, bbSeat);
    state.toActSeat = firstToActSeat;
    if (state.toActSeat === -1) {
      throw new PokerError("BAD_STATE", "No seat needs action at hand start.");
    }
    const toActId = state.seats[state.toActSeat] ?? "";
    const toActPlayer = toActId ? state.playersById.get(toActId) : undefined;
    if (!toActPlayer || toActPlayer.status !== "ACTIVE" || !toActPlayer.needsAction) {
      throw new PokerError("BAD_STATE", "toAct must be ACTIVE with needsAction at hand start.");
    }

    if (bbId && !isHeadsUp) {
      const bb = state.playersById.get(bbId);
      if (bb) bb.needsAction = false;
    }

    logger.info({ handId: state.handId }, "hand started");
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "HAND_START" });
    plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    maybeAssertBettingState(state);
    maybeAssertStateInvariants(state);
    return plans;
  }

  /**
   * Advance to next street or proceed to showdown
   * 
   * DECISION LOGIC:
   * 1. Check if betting is complete (all-in/folded or no further betting)
   * 2. If complete → runout to showdown
   * 3. If not complete → deal community cards for next street
   * 4. Set up next action and validate state
   * 
   * @returns Array of lifecycle plans for street transition
   */
  async advanceStreetOrShowdown(): Promise<HandLifecyclePlan[]> {
    const plans: HandLifecyclePlan[] = [];
    const { state } = this.deps;
    const totalStacksBeforeCents = this.sumStacksCents();
    const potCentsBefore = state.potCents;
    const disbursedBefore = this.deps.settlementService.getCurrentHandPotDisbursedCents();
    if (state.street === "WAITING") {
      throw new PokerError("BAD_STATE", "advanceStreetOrShowdown while WAITING.");
    }
    if (
      state.runoutMode === "STAGED" &&
      !allRemainingPlayersAllInOrFolded(state) &&
      !noFurtherBettingPossible(state)
    ) {
      throw new PokerError("BAD_STATE", "STAGED runout entered while betting is still possible.");
    }

    if (
      state.runoutMode === "STAGED" ||
      allRemainingPlayersAllInOrFolded(state) ||
      noFurtherBettingPossible(state)
    ) {
      state.runoutMode = "STAGED";
      return this.finishHandShowdownWithSidePots();
    }

    const next = this.nextStreet(state.street);
    if (next === "SHOWDOWN") {
      state.street = "SHOWDOWN";
      return this.finishHandShowdownWithSidePots();
    }

    state.street = next;
    state.runoutMode = "NONE";
    this.dealCommunityForStreet(next);

    resetBettingRound(state);
    this.applyNeedsActionForCurrentHand();
    state.toActSeat = findNextToActSeat(state, state.dealerSeat);
    if (state.toActSeat === -1) {
      // Churn windows can transition streets with no actionable seat (all-in/folded/abandoned mix).
      // In this case run out directly to showdown instead of surfacing BAD_STATE.
      state.runoutMode = "STAGED";
      return this.finishHandShowdownWithSidePots();
    }

    const toActUserId = state.seats[state.toActSeat] ?? "";
    logger.info(
      { tableId: state.tableId, handId: state.handId, street: next, toActSeat: state.toActSeat, toActUserId },
      "STREET_ADVANCE_COMPLETED",
    );
    logger.info(
      { tableId: state.tableId, handId: state.handId, street: next, toActSeat: state.toActSeat, toActUserId },
      "NEXT_ACTOR_SELECTED",
    );

    plans.push({ kind: "EMIT_SNAPSHOT", reason: "AUTO_TRANSITION" });
    plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    assertMoneyConservationTransition({
      event: "STREET_SETTLE",
      actionType: "STREET_TRANSITION",
      street: state.street,
      state,
      potCentsBefore,
      potCentsAfter: state.potCents,
      totalStacksBeforeCents,
      totalStacksAfterCents: this.sumStacksCents(),
      potDisbursedCentsBefore: disbursedBefore,
      potDisbursedCentsAfter: this.deps.settlementService.getCurrentHandPotDisbursedCents(),
      expectedPotDeltaCents: 0,
      expectedMassDeltaCents: 0,
    });
    maybeAssertBettingState(state);
    maybeAssertStateInvariants(state);
    return plans;
  }

  // ============================================================================
  // HAND COMPLETION METHODS
  // ============================================================================

  /**
   * Complete hand when only one player remains (last standing)
   * 
   * SCENARIOS:
   * 1. NORMAL: One ACTIVE/ALL_IN player vs folded opponents
   * 2. DEFENSIVE: No active players (corruption/edge case)
   * 
   * PROCESS:
   * 1. Return uncalled chips to aggressor
   * 2. Credit remaining pot to winner
   * 3. Validate chip conservation
   * 4. Generate hand result and cleanup plans
   * 
   * @returns Array of lifecycle plans for hand completion
   */
  async finishHandByLastStanding(): Promise<HandLifecyclePlan[]> {
    const plans: HandLifecyclePlan[] = [];
    const { state } = this.deps;
    const remaining = [...state.playersById.values()].filter(
      (p) => p.status === "ACTIVE" || p.status === "ALL_IN",
    );
    const notFoldedOrOut = [...state.playersById.values()].filter(
      (p) => p.status !== "FOLDED" && p.status !== "OUT" && p.status !== "ABANDONED",
    );

    // ── DEFENSIVE FALLBACK: no ACTIVE/ALL_IN players remain ──────────────────
    // e.g. a sole survivor who is ABANDONED with chips.
    if (remaining.length === 0) {
      let winner: typeof notFoldedOrOut[0];
      let creditAmount: number;
      const payoutsByUserId: Record<string, number> = {};

      if (notFoldedOrOut.length === 1) {
        winner = notFoldedOrOut[0]!;
      } else {
        // Deterministic: pick earliest seat left of dealer among survivors
        winner = seatOrderLeftOfDealer(state)
          .map((id) => state.playersById.get(id))
          .find((p) => p && p.status !== "FOLDED" && p.status !== "OUT" && p.status !== "ABANDONED")!;
      }

      // Step 1: Return any uncalled chips (prevents pot inflation)
      const { cents: uncalledCents, playerId: uncalledPlayerId } = this.calculateUncalledCents(state);
      if (uncalledCents > 0 && uncalledPlayerId) {
        const uncalledPlayer = state.playersById.get(uncalledPlayerId);
        if (uncalledPlayer) {
          await this.deps.settlementService.creditRefundToPlayer(uncalledPlayer, uncalledCents, "UNCALLED_BET_RETURN");
          payoutsByUserId[uncalledPlayer.id] = (payoutsByUserId[uncalledPlayer.id] ?? 0) + uncalledCents;
        }
      }

      // Step 2: Disburse exactly what remains in the pot
      const disbursedCents = this.deps.settlementService.getCurrentHandPotDisbursedCents();
      creditAmount = state.potCents - disbursedCents;
      await this.deps.settlementService.creditPayoutToPlayer(winner, creditAmount);
      payoutsByUserId[winner.id] = (payoutsByUserId[winner.id] ?? 0) + creditAmount;

      this.assertHandMassOrThrow(state, "HAND_END_LAST_STANDING_DEFENSIVE_POST_PAYOUT", true);
      await this.deps.applyDisconnectedAutoActionCapForHand();
      syncRoundCurrentBetCents(state);
      await this.deps.settlementService.finalizePersistedHand("ALL_FOLDED");
      this.assertHandMassOrThrow(state, "HAND_END_LAST_STANDING_DEFENSIVE_PRE_FINALIZE", true);
      this.assertHandResultPayoutsOrThrow(payoutsByUserId, state.potCents, "HAND_END_LAST_STANDING_DEFENSIVE");
      this.deps.setLastHandResult({
        handId: state.handId,
        reason: "LAST_PLAYER",
        potCents: state.potCents,
        winnerId: winner.id,
        payoutsByUserId,
        board: [...state.board],
      });
      this.assertHandMassOrThrow(state, "HAND_END_LAST_STANDING_DEFENSIVE", true);
      plans.push({ kind: "EMIT_SNAPSHOT", reason: "HAND_END" });
      plans.push({
        kind: "HAND_ENDED",
        reason: "DEFENSIVE_FALLBACK",
        outcome: {
          potCents: state.potCents,
          winnerId: winner.id,
          payoutsByUserId,
        },
      });
      plans.push({ kind: "TRANSITION_TO_WAITING" });
      plans.push({ kind: "RELEASE_PENDING_SEATS" });
      plans.push({ kind: "SCHEDULE_NEXT_HAND", reason: "HAND_END", delayMs: HAND_RESULT_HOLD_MS });
      if (this.deps.persistence.enabled && this.shouldAssertLedgerForCurrentHand()) {
        await this.deps.persistence.assertHandBalanced(state.handId);
      }
      this.assertHandMassOrThrow(state, "HAND_END_LAST_STANDING_DEFENSIVE", true);
      maybeAssertStateInvariants(state);
      return plans;
    }

    if (notFoldedOrOut.length > 1) {
      throw new PokerError("BAD_STATE", "finishHandByLastStanding: no ACTIVE/ALL_IN but multiple non-folded players.");
    }
    if (remaining.length !== 1) {
      throw new PokerError("BAD_STATE", "finishHandByLastStanding called with != 1 remaining player.");
    }

    // ── NORMAL LAST-STANDING: winner is the one remaining ACTIVE/ALL_IN player ──
    const winner = remaining[0]!;
    const payoutsByUserId: Record<string, number> = {};

    // Step 1: Identify and return uncalled chips before touching the pot.
    // Example: A bets 1000, B (100 chips) folds → A's 900 is uncalled and must be returned.
    const { cents: uncalledCents, playerId: uncalledPlayerId } = this.calculateUncalledCents(state);
    if (uncalledCents > 0 && uncalledPlayerId) {
      const uncalledPlayer = state.playersById.get(uncalledPlayerId);
      if (uncalledPlayer) {
        logger.info(
          { handId: state.handId, playerId: uncalledPlayerId, uncalledCents },
          "Returning uncalled bet before last-standing payout",
        );
        await this.deps.settlementService.creditRefundToPlayer(uncalledPlayer, uncalledCents, "UNCALLED_BET_RETURN");
        payoutsByUserId[uncalledPlayer.id] = (payoutsByUserId[uncalledPlayer.id] ?? 0) + uncalledCents;
      }
    }

    // Step 2: Disburse exactly what remains in the pot after the refund.
    // creditRefundToPlayer increments disbursedCents, so this naturally clears the pot.
    const disbursedCents = this.deps.settlementService.getCurrentHandPotDisbursedCents();
    const creditAmount = state.potCents - disbursedCents;
    await this.deps.settlementService.creditPayoutToPlayer(winner, creditAmount);
    payoutsByUserId[winner.id] = (payoutsByUserId[winner.id] ?? 0) + creditAmount;

    // Step 3: Assert 100% of the pot is cleared.
    this.assertHandMassOrThrow(state, "HAND_END_LAST_STANDING_POST_PAYOUT", true);
    await this.deps.applyDisconnectedAutoActionCapForHand();
    syncRoundCurrentBetCents(state);
    await this.deps.settlementService.finalizePersistedHand("ALL_FOLDED");
    this.assertHandMassOrThrow(state, "HAND_END_LAST_STANDING_PRE_FINALIZE", true);
    this.assertHandResultPayoutsOrThrow(payoutsByUserId, state.potCents, "HAND_END_LAST_STANDING");
    this.deps.setLastHandResult({
      handId: state.handId,
      reason: "LAST_PLAYER",
      potCents: state.potCents,
      winnerId: winner.id,
      payoutsByUserId,
      board: [...state.board],
    });
    this.assertHandMassOrThrow(state, "HAND_END_LAST_STANDING", true);
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "HAND_END" });
    plans.push({
      kind: "HAND_ENDED",
      reason: "LAST_PLAYER",
      outcome: {
        potCents: state.potCents,
        winnerId: winner.id,
        payoutsByUserId,
      },
    });
    plans.push({ kind: "TRANSITION_TO_WAITING" });
    plans.push({ kind: "RELEASE_PENDING_SEATS" });
    plans.push({ kind: "SCHEDULE_NEXT_HAND", reason: "HAND_END", delayMs: HAND_RESULT_HOLD_MS });
    maybeAssertStateInvariants(state);
    if (this.deps.persistence.enabled && this.shouldAssertLedgerForCurrentHand()) {
      await this.deps.persistence.assertHandBalanced(state.handId);
    }
    return plans;
  }

  /**
   * Complete hand with showdown and side pot distribution
   * 
   * PROCESS:
   * 1. Run out community cards if not already at showdown
   * 2. Evaluate all eligible hands using poker solver
   * 3. Build and distribute side pots to winners
   * 4. Reconcile any remainder chips (deterministic seat order)
   * 5. Validate total payouts equal pot size
   * 6. Generate hand result with hole cards for display
   * 
   * DETERMINISM:
   * - Remainder chips go to earliest seat left of dealer
   * - No randomness in any settlement calculations
   * 
   * @returns Array of lifecycle plans for showdown completion
   */
  async finishHandShowdownWithSidePots(): Promise<HandLifecyclePlan[]> {
    const plans: HandLifecyclePlan[] = [];
    const { state } = this.deps;
    if (state.street !== "SHOWDOWN") {
      plans.push(...this.runoutToRiverStaged());
      // Street is forced to SHOWDOWN after staged runout.
      state.street = "SHOWDOWN";
    }

    const playersAll = [...state.playersById.values()].filter((player) => player.status !== "OUT");
    const eligible = playersAll.filter(eligibleForShowdown);
    
    // Guard against eligibleForShowdown bugs - this should never fire if filter is correct
    if (eligible.some((p) => p.status === "FOLDED")) {
      throw new PokerError("BAD_STATE", "eligibleForShowdown returned folded player - filter logic bug.");
    }

    if (eligible.length <= 1) {
      return this.finishHandByLastStanding();
    }

    const pots = buildSidePots(playersAll, eligible);
    const board = [...state.board];
    const playersArray = [...state.playersById.values()];

    const holeCards = this.getHoleCardsByPlayerIdSafe();
    const solved = new Map<string, SolvedHand>();
    for (const player of eligible) {
      const cards = holeCards.get(player.id) ?? [];
      if (cards.length !== 2) {
        throw new PokerError("BAD_STATE", `Missing hole cards at showdown for player ${player.id}.`);
      }
      solved.set(player.id, Hand.solve([...cards, ...board]) as SolvedHand);
    }

    const seatOrder = seatOrderLeftOfDealer(state);
    const payouts = new Map<string, number>();

    for (const pot of pots) {
      const contenders = pot.eligiblePlayerIds;
      if (contenders.length === 0) continue;

      const hands = contenders.map((id) => solved.get(id)).filter(Boolean);
      const winners = Hand.winners(hands);
      const winnerSet = new Set(winners);
      
      const winnerIds: string[] = [];
      for (const id of contenders) {
        const hand = solved.get(id);
        if (hand && winnerSet.has(hand)) winnerIds.push(id);
      }

      const split = splitPotCents(pot.amountCents, winnerIds, seatOrder);
      for (const [id, amount] of split.entries()) {
        payouts.set(id, (payouts.get(id) ?? 0) + amount);
      }
    }

    const totalPaidBeforeReconcile = [...payouts.values()].reduce((sum, amount) => sum + amount, 0);
    if (totalPaidBeforeReconcile < state.potCents && eligible.length > 0) {
      const remainder = state.potCents - totalPaidBeforeReconcile;
      const seatOrderIndex = new Map<string, number>();
      seatOrder.forEach((id, idx) => seatOrderIndex.set(id, idx));

      // Industry standard: remainder chip goes to the first eligible player
      // to the left of the dealer button (smallest seatOrderIndex).
      const fallbackRecipient = [...eligible].sort((a, b) => {
        const ai = seatOrderIndex.get(a.id) ?? Number.MAX_SAFE_INTEGER;
        const bi = seatOrderIndex.get(b.id) ?? Number.MAX_SAFE_INTEGER;
        return ai - bi; // deterministic: earliest seat left of dealer gets remainder
      })[0];

      if (fallbackRecipient) {
        if (shouldFailClosedMoneyPath()) {
          throw new PokerError(
            "BAD_STATE",
            `SHOWDOWN_REMAINDER_RECONCILED: pot=${state.potCents}, paid=${totalPaidBeforeReconcile}, remainder=${remainder}, recipient=${fallbackRecipient.id}, hand=${state.handId}`,
          );
        }
        payouts.set(fallbackRecipient.id, (payouts.get(fallbackRecipient.id) ?? 0) + remainder);
        // Production should alert on this event; silent chip reconciliation masks side-pot bugs.
        logger.warn(
          {
            handId: state.handId,
            potCents: state.potCents,
            paidCents: totalPaidBeforeReconcile,
            remainderCents: remainder,
            fallbackRecipientUserId: fallbackRecipient.id,
            event: "SHOWDOWN_REMAINDER_RECONCILED",
          },
          "showdown payout remainder reconciled; investigate uncalled/side-pot edge",
        );
      }
    }

    const payoutSum = [...payouts.values()].reduce((sum, amount) => sum + amount, 0);
    if (payoutSum !== state.potCents) {
      throw new PokerError("BAD_STATE", "Payout sum must equal pot.");
    }

    for (const [id, amount] of payouts.entries()) {
      const player = state.playersById.get(id);
      if (player) {
        await this.deps.settlementService.creditPayoutToPlayer(player, amount);
      }
    }
    this.assertHandMassOrThrow(state, "HAND_END_SHOWDOWN_POST_PAYOUT_BATCH", true);

    const payoutsEntries = [...payouts.entries()];
    const primaryWinnerId = seatOrder.find((id) => payouts.has(id));
    const displayWinnerId = payoutsEntries.length === 1 ? primaryWinnerId : undefined;
    const primaryWinnerCards = primaryWinnerId ? holeCards.get(primaryWinnerId) : undefined;
    const primarySolved = primaryWinnerId ? solved.get(primaryWinnerId) : undefined;
    const winningDescr = primarySolved?.descr ?? primarySolved?.name;
    const showdownHoleCardsByUserId: Record<string, [string, string]> = {};
    for (const player of eligible) {
      const cards = holeCards.get(player.id);
      if (cards?.length === 2) {
        showdownHoleCardsByUserId[player.id] = [cards[0]!, cards[1]!];
      }
    }

    await this.deps.applyDisconnectedAutoActionCapForHand();
    syncRoundCurrentBetCents(state);
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "HAND_SHOWDOWN" });

    this.assertHandMassOrThrow(state, "HAND_END_SHOWDOWN_POST_FINALIZE", true);
    await this.deps.settlementService.finalizePersistedHand("SHOWDOWN");
    const payoutsByUserId = Object.fromEntries(payoutsEntries);
    this.assertHandResultPayoutsOrThrow(payoutsByUserId, state.potCents, "HAND_END_SHOWDOWN");
    this.deps.setLastHandResult({
      handId: state.handId,
      reason: "SHOWDOWN",
      potCents: state.potCents,
      winnerId: displayWinnerId,
      payoutsByUserId,
      board,
      showdownHoleCardsByUserId,
      winnerHoleCards: primaryWinnerCards?.length === 2 ? primaryWinnerCards : undefined,
      winningHandDescr: typeof winningDescr === "string" ? winningDescr : undefined,
    });
    this.assertHandMassOrThrow(state, "HAND_END_SHOWDOWN_POST_FINALIZE", true);
    plans.push({ 
      kind: "HAND_ENDED", 
      reason: "SHOWDOWN", 
      outcome: { 
        potCents: state.potCents, 
        winnerId: displayWinnerId, 
        payoutsByUserId
      } 
    });
    plans.push({ kind: "TRANSITION_TO_WAITING" });
    plans.push({ kind: "RELEASE_PENDING_SEATS" });
    plans.push({ kind: "SCHEDULE_NEXT_HAND", reason: "HAND_END", delayMs: HAND_RESULT_HOLD_MS });
    
    this.assertHandMassOrThrow(state, "HAND_END_SHOWDOWN_POST_FINALIZE", true);
    maybeAssertStateInvariants(state);
    if (this.deps.persistence.enabled && this.shouldAssertLedgerForCurrentHand()) {
      await this.deps.persistence.assertHandBalanced(state.handId);
    }
    return plans;
  }

  // ============================================================================
  // HELPER METHODS - Street Transitions & Card Dealing
  // ============================================================================

  /**
   * Draw a card from the deck
   * @throws PokerError if deck is not initialized
   * @returns Next card from deck
   */
  private drawCard(): string {
    if (!this.deck) throw new PokerError("BAD_STATE", "Deck not initialized.");
    return this.deck.draw();
  }

  /**
   * Determine the next street in poker sequence
   * @param street Current street
   * @returns Next street or throws if invalid
   */
  private nextStreet(street: Street): Street {
    if (street === "PREFLOP") return "FLOP";
    if (street === "FLOP") return "TURN";
    if (street === "TURN") return "RIVER";
    if (street === "RIVER") return "SHOWDOWN";
    throw new PokerError("BAD_STATE", `Unknown street ${street}.`);
  }

  /**
   * Deal community cards for the specified street
   * 
   * DEALING RULES:
   * - FLOP: 3 cards
   * - TURN: 1 card
   * - RIVER: 1 card
   * 
   * @param street Street to deal cards for
   */
  private dealCommunityForStreet(street: Street): void {
    if (street === "FLOP") this.deps.state.board.push(this.drawCard(), this.drawCard(), this.drawCard());
    else if (street === "TURN" || street === "RIVER") this.deps.state.board.push(this.drawCard());
  }

  /**
   * Generate staged runout plans for all-in scenarios
   * 
   * PROCESS:
   * 1. Progress through remaining streets (FLOP → TURN → RIVER)
   * 2. Deal community cards with delays between streets
   * 3. Create snapshot and delay plans for each stage
   * 
   * NOTE: This mutates state while building plans
   * Execution layer must run plans in order to maintain proper timing
   * 
   * @returns Array of staged runout plans
   */
  private runoutToRiverStaged(): HandLifecyclePlan[] {
    const plans: HandLifecyclePlan[] = [];
    // NOTE: This function mutates state while constructing plans.
    // It is only called from lifecycle transitions where immediate mutation is intended.
    // The execution layer (Dealer) must run plans in order and honor DELAY steps;
    // skipping or reordering would show community cards without the intended pause.
    while (this.deps.state.street !== "RIVER") {
      const next = this.nextStreet(this.deps.state.street);
      if (next === "SHOWDOWN") break;
      this.deps.state.street = next;
      this.dealCommunityForStreet(next);
      maybeAssertBettingState(this.deps.state);
      plans.push({ kind: "EMIT_SNAPSHOT", reason: "RUNOUT_STAGE" });
      plans.push({ kind: "DELAY", ms: RUNOUT_STAGE_DELAY_MS });
    }
    return plans;
  }
}

import type { HandLifecyclePlan } from "./HandLifecycleService.js";
import type { PlayerLifecyclePlan } from "./PlayerLifecycleService.js";
import type { SnapshotReason } from "./SnapshotService.js";

const delay = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));
type HandEndedPlan = Extract<HandLifecyclePlan, { kind: "HAND_ENDED" }>;
type DeferredRemovalPlan = Extract<PlayerLifecyclePlan, { kind: "LIFECYCLE_DEFERRED_REMOVAL" }>;
type LifecycleExecutorDeps = {
  sendTableSnapshotToAll: (reason: SnapshotReason, actionId?: string) => Promise<void>;
  isDisposed?: () => boolean;
  flushSessionStatsOnly: () => void;
  maybeActForBot: () => void;
  transitionToWaiting: () => void;
  releasePendingSeats: () => Promise<void>;
  scheduleNextHand: (reason: string, delayMs?: number) => void;
  runHandEndedAwards: (plan: HandEndedPlan) => Promise<void>;
  onHandEndedAwardsFailed: (err: unknown) => void;
  onLifecycleDeferredRemoval: (plan: DeferredRemovalPlan) => void;
  startHand: () => Promise<void>;
  ensureHandAdvancingAfterPlayerRemoval: (removedSeat: number) => Promise<void>;
  finishHandByLastStanding: () => Promise<void>;
  advanceStreetOrShowdown: () => Promise<void>;
};

export class LifecycleExecutor {
  constructor(private readonly deps: LifecycleExecutorDeps) {}

  async executeHandLifecyclePlans(plans: HandLifecyclePlan[]): Promise<void> {
    if (this.deps.isDisposed?.()) return;
    for (const plan of plans) {
      switch (plan.kind) {
        case "EMIT_SNAPSHOT":
          if (plan.reason === "HAND_END") this.deps.flushSessionStatsOnly();
          await this.deps.sendTableSnapshotToAll(plan.reason, plan.actionId);
          break;
        case "DELAY":
          await delay(plan.ms);
          break;
        case "MAYBE_AUTOMATE_TURN":
          this.deps.maybeActForBot();
          break;
        case "TRANSITION_TO_WAITING":
          this.deps.transitionToWaiting();
          break;
        case "RELEASE_PENDING_SEATS":
          await this.deps.releasePendingSeats();
          break;
        case "SCHEDULE_NEXT_HAND":
          this.deps.scheduleNextHand(plan.reason, plan.delayMs ?? 0);
          break;
        case "HAND_ENDED":
          try {
            await this.deps.runHandEndedAwards(plan);
          } catch (err) {
            this.deps.onHandEndedAwardsFailed(err);
          }
          break;
        default: {
          const _exhaustive: never = plan;
          throw new Error("Unhandled hand lifecycle plan");
        }
      }
    }
  }

  async executePlayerLifecyclePlans(plans: PlayerLifecyclePlan[]): Promise<void> {
    if (this.deps.isDisposed?.()) return;
    for (const plan of plans) {
      switch (plan.kind) {
        case "EMIT_SNAPSHOT":
          await this.deps.sendTableSnapshotToAll(plan.reason, plan.actionId);
          break;
        case "LIFECYCLE_DEFERRED_REMOVAL":
          this.deps.onLifecycleDeferredRemoval(plan);
          break;
        case "MAYBE_AUTOMATE_TURN":
          this.deps.maybeActForBot();
          break;
        case "START_HAND":
          await this.deps.startHand();
          break;
        case "ENSURE_HAND_ADVANCING_AFTER_PLAYER_REMOVAL":
          await this.deps.ensureHandAdvancingAfterPlayerRemoval(plan.removedSeat);
          break;
        case "RELEASE_PENDING_SEATS":
          await this.deps.releasePendingSeats();
          break;
        case "FINISH_HAND_BY_LAST_STANDING":
          await this.deps.finishHandByLastStanding();
          break;
        case "ADVANCE_STREET_OR_SHOWDOWN":
          await this.deps.advanceStreetOrShowdown();
          break;
        default: {
          const _exhaustive: never = plan;
          throw new Error("Unhandled player lifecycle plan");
        }
      }
    }
  }
}

/**
 * PlayerLifecycleService - Player State Management & Lifecycle Events
 * 
 * PURPOSE:
 * Manages player lifecycle events including joining, leaving, reconnection,
 * disconnection, abandonment, and state transitions. Handles player
 * seating, cash operations, and automated actions.
 * 
 * KEY RESPONSIBILITIES:
 * - Player seating and table management
 * - Connection/disconnection handling
 * - Cash-out and rebuy processing
 * - State validation and invariants
 * - Automated action management
 * 
 * CONCURRENCY SAFETY:
 * Uses idempotency keys and tracking sets to prevent race conditions
 * when multiple operations affect the same player simultaneously.
 * 
 * USAGE:
 * const service = new PlayerLifecycleService(dependencies);
 * const plans = await service.addPlayer(userId, name, buyInCents);
 * // Execute plans through Dealer execution layer
 */

// ============================================================================
// IMPORTS - External Dependencies
// ============================================================================
import { nanoid } from "nanoid";

// ============================================================================
// IMPORTS - Internal Dependencies
// ============================================================================
import { logger } from "../../../lib/logger.js";
import type { PokerState } from "../../../state/PokerState.js";
import { PlayerState } from "../../../state/PlayerState.js";
import { PokerError } from "../../errors.js";
import type { PersistenceFacade } from "../../persistence/PersistenceFacade.js";
import { CashierService } from "../../economy/CashierService.js";

// ============================================================================
// IMPORTS - Poker Rules & Game Logic
// ============================================================================
import {
  bettingRoundComplete,
  eligibleToAct,
  noFurtherBettingPossible,
  syncRoundCurrentBetCents,
} from "../../rules/BettingRound.js";

// ============================================================================
// IMPORTS - Utilities & Helpers
// ============================================================================
import { countNonOutPlayers, countNotFoldedPlayers, findNextToActSeat, findOpenSeat } from "../utils/TableNavigator.js";
import { RECONNECT_GRACE_DEFAULT_MS } from "../timing.js";

// ============================================================================
// IMPORTS - Invariants & Validation
// ============================================================================
import { maybeAssertStateInvariants } from "../../invariants/assertState.js";

// ============================================================================
// IMPORTS - Type Definitions
// ============================================================================
import type { SnapshotReason } from "./SnapshotService.js";

// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

/**
 * Plan types for player lifecycle management
 * Each plan represents an atomic operation that can be executed by the Dealer
 * to manage player state transitions and table events.
 */
export type PlayerLifecyclePlan =
  | { kind: "EMIT_SNAPSHOT"; reason: SnapshotReason; actionId?: string }
  | { kind: "LIFECYCLE_DEFERRED_REMOVAL"; userId: string; reason: string }
  | { kind: "MAYBE_AUTOMATE_TURN" }
  | { kind: "START_HAND" }
  | { kind: "ENSURE_HAND_ADVANCING_AFTER_PLAYER_REMOVAL"; removedSeat: number }
  | { kind: "RELEASE_PENDING_SEATS" }
  | { kind: "FINISH_HAND_BY_LAST_STANDING" }
  | { kind: "ADVANCE_STREET_OR_SHOWDOWN" };

/**
 * Function type for forcing player folds during hand progression
 * Used by Dealer to maintain game consistency when players abandon
 */
export type ForceFoldIfInHand = (userId: string) => Promise<void>;

// ============================================================================
// MAIN CLASS - Player Lifecycle Management
// ============================================================================

/**
 * PlayerLifecycleService - Core service for managing player state and lifecycle events
 * 
 * This class handles all player-related operations including joining, leaving,
 * reconnection, cash operations, and state transitions. It provides
 * concurrency safety through idempotency tracking and validation.
 */
export class PlayerLifecycleService {
  // ============================================================================
  // CLASS PROPERTIES - Concurrency & State Tracking
  // ============================================================================
  
  /** Prevents duplicate cash-out when leave/cash-out is triggered from multiple paths. */
  private readonly cashedOutUserIds = new Set<string>();
  /** Prevents duplicate removePlayer/leave from running concurrently for the same user. */
  private readonly leaveInProgressUserIds = new Set<string>();
  /** Prevents duplicate rebuy state mutation when the same idempotency key is replayed. */
  private readonly appliedRebuyKeys = new Set<string>();

  // ============================================================================
  // CONSTRUCTOR & DEPENDENCIES
  // ============================================================================
  
  /**
   * Initialize PlayerLifecycleService with required dependencies
   * @param deps - Service dependencies for state, persistence, and player management
   */
  constructor(private readonly deps: {
    state: PokerState;
    persistence: PersistenceFacade;
    pendingSeatReleaseUserIds: Set<string>;
    autoActionsByUserId: Map<string, number>;
    currentHandAutoActedUserIds: Set<string>;
    getHoleCardsByPlayerId: () => Map<string, string[]>;
    ensurePlayerPersistence: (player: PlayerState) => Promise<void>;
    /** When set, used to force-fold before abandon/remove so hand history and pot math are consistent. */
    forceFoldIfInHand?: ForceFoldIfInHand;
  }) {}

  // ============================================================================
  // PLAYER LIFECYCLE METHODS
  // ============================================================================

  /**
   * Add a new player to the table with buy-in
   * 
   * PROCESS:
   * 1. Validate player doesn't already exist
   * 2. Find available seat and assign to player
   * 3. Process buy-in through cashier service
   * 4. Update player state and persistence
   * 5. Generate plans for table state updates
   * 
   * CONCURRENCY SAFETY:
   * - Uses idempotency key for rebuy operations
   * - Validates no duplicate player addition
   * 
   * @param userId Unique player identifier
   * @param name Display name for player
   * @param buyInCents Amount to add to player stack
   * @returns Array of lifecycle plans for player addition
   */
  async addPlayer(userId: string, name: string, buyInCents: number): Promise<PlayerLifecyclePlan[]> {
    logger.info({ userId, buyInCents }, 'addPlayer called');
    const plans: PlayerLifecyclePlan[] = [];
    if (this.deps.state.playersById.has(userId)) {
      logger.info({ userId }, 'addPlayer early return - player already exists');
      return plans;
    }
    this.cashedOutUserIds.delete(userId);

    const seat = findOpenSeat(this.deps.state);
    if (seat === -1) throw new PokerError("TABLE_FULL", "Table is full.");
    this.assertValidBuyIn(buyInCents);

    const externalRef = `buyin_${this.deps.state.tableId}_${userId}_${Date.now()}_${nanoid(6)}`;
    let buyInTableBalance = buyInCents;
    try {
      const result = await CashierService.processCashGameBuyIn({
        userId,
        tableId: this.deps.state.tableId,
        amountCents: buyInCents,
        externalRef,
        tableMeta: {
          name: this.deps.state.tableName,
        },
      });
      buyInTableBalance = result.newTableBalance;
      logger.info({ userId, buyInCents, newTableBalance: result.newTableBalance }, "buy-in processed");
    } catch (err: any) {
      if (err.message === "INSUFFICIENT_BANKROLL") {
        throw new PokerError("INSUFFICIENT_BANKROLL", "Insufficient bankroll for this buy-in.");
      }
      throw err;
    }

    const player = new PlayerState();
    player.id = userId;
    player.userId = userId;
    player.kind = "HUMAN";
    player.name = name;
    player.seat = seat;
    player.status = this.deps.state.street === "WAITING" ? "ACTIVE" : "ABANDONED";
    player.connected = true;
    player.disconnectDeadlineTs = 0;
    player.stackCents = buyInTableBalance;
    player.roundBetCents = 0;
    player.committedCents = 0;
    player.needsAction = false;
    player.sittingOutUntilNextHand = this.deps.state.street !== "WAITING";

    this.deps.state.playersById.set(userId, player);
    this.deps.state.seats[seat] = userId;
    if (this.deps.state.street !== "WAITING" && this.deps.state.initialChipMassCents > 0) {
      this.deps.state.initialChipMassCents += buyInTableBalance;
    }

    this.ensureToActHasNeedsActionIfNeeded(seat, userId);

    await this.deps.ensurePlayerPersistence(player);
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });

    logger.info({ userId, seat }, "player joined");
    if (countNonOutPlayers(this.deps.state) >= 2 && this.deps.state.street === "WAITING") {
      plans.push({ kind: "START_HAND" });
    } else {
      if (this.deps.state.street !== "WAITING") {
        player.status = "ABANDONED";
      }
      player.sittingOutUntilNextHand = true;
      plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    }
    maybeAssertStateInvariants(this.deps.state);
    return plans;
  }

  /**
   * Add chips to an already-seated player (rebuy). Caller must have already run
   * CashierService.processCashGameBuyIn so ledger is updated; this only mutates in-memory state.
   */
  async addChipsToSeatedPlayer(userId: string, amountCents: number, rebuyRef?: string): Promise<PlayerLifecyclePlan[]> {
    const plans: PlayerLifecyclePlan[] = [];
    const player = this.deps.state.playersById.get(userId);
    if (!player) return plans;
    this.assertValidBuyIn(amountCents);
    if (rebuyRef) {
      const rebuyKey = `${userId}:${rebuyRef}`;
      if (this.appliedRebuyKeys.has(rebuyKey)) {
        logger.warn({ userId, rebuyRef }, "Duplicate rebuy state mutation prevented");
        return plans;
      }
      this.appliedRebuyKeys.add(rebuyKey);
    }
    player.stackCents += amountCents;
    if (this.deps.state.street !== "WAITING" && this.deps.state.initialChipMassCents > 0) {
      this.deps.state.initialChipMassCents += amountCents;
    }
    if (player.status === "OUT" || player.status === "ABANDONED") {
      player.sittingOutUntilNextHand = false;
      if (this.deps.state.street === "WAITING") {
        player.status = "ACTIVE";
      }
    }
    await this.deps.ensurePlayerPersistence(player);
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });
    logger.info({ userId, amountCents, newStackCents: player.stackCents }, "rebuy applied");
    if (countNonOutPlayers(this.deps.state) >= 2 && this.deps.state.street === "WAITING") {
      plans.push({ kind: "START_HAND" });
    }
    return plans;
  }

  async restorePlayerFromSession(
    userId: string,
    name: string,
    seat: number,
    stackCents: number,
    options?: { connected?: boolean; sittingOut?: boolean; reconnectTimeoutMs?: number },
  ): Promise<PlayerLifecyclePlan[]> {
    const plans: PlayerLifecyclePlan[] = [];
    if (this.deps.state.playersById.has(userId)) return plans;
    this.cashedOutUserIds.delete(userId);
    if (seat < 0 || seat >= this.deps.state.seats.length) {
      throw new PokerError("BAD_STATE", "Invalid seat from persisted session.");
    }

    const occupant = this.deps.state.seats[seat];
    if (occupant && occupant !== userId) {
      throw new PokerError("BAD_STATE", "Persisted seat is currently occupied.");
    }

    const connected = options?.connected ?? true;
    const sittingOut = options?.sittingOut ?? false;
    const reconnectTimeoutMs = options?.reconnectTimeoutMs ?? 0;

    const player = new PlayerState();
    player.id = userId;
    player.userId = userId;
    player.kind = "HUMAN";
    player.name = name;
    player.seat = seat;

    player.status = stackCents > 0 ? (sittingOut ? "ABANDONED" : "ACTIVE") : "OUT";
    player.connected = connected;
    // Disconnected humans must have a future deadline so cap/sweep don't treat them as past grace.
    player.disconnectDeadlineTs =
      !connected
        ? Date.now() + (reconnectTimeoutMs > 0 ? reconnectTimeoutMs : RECONNECT_GRACE_DEFAULT_MS)
        : 0;
    player.stackCents = Math.max(0, stackCents);
    player.roundBetCents = 0;
    player.committedCents = 0;
    player.needsAction = false;

    this.deps.state.playersById.set(userId, player);
    this.deps.autoActionsByUserId.delete(userId);
    this.deps.state.seats[seat] = userId;

    this.ensureToActHasNeedsActionIfNeeded(seat, userId);

    await this.deps.ensurePlayerPersistence(player);
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "RECONNECT" });

    logger.info({ userId, seat, stackCents: player.stackCents }, "player restored from persisted seat session");
    if (countNonOutPlayers(this.deps.state) >= 2 && this.deps.state.street === "WAITING") {
      plans.push({ kind: "START_HAND" });
    } else {
      plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    }
    maybeAssertStateInvariants(this.deps.state);
    return plans;
  }

  async addBot(botId: string, name: string, buyInCents: number, catalogBotId?: string): Promise<PlayerLifecyclePlan[]> {
    const plans: PlayerLifecyclePlan[] = [];
    if (this.deps.state.playersById.has(botId)) return plans;

    const seat = findOpenSeat(this.deps.state);
    if (seat === -1) throw new PokerError("TABLE_FULL", "Table is full.");
    this.assertValidBuyIn(buyInCents);

    const player = new PlayerState();
    player.id = botId;
    player.userId = "";
    player.kind = "BOT";
    player.botId = catalogBotId || botId;
    player.name = name;
    player.seat = seat;
    player.status = this.deps.state.street === "WAITING" ? "ACTIVE" : "ABANDONED";
    player.connected = true;
    player.disconnectDeadlineTs = 0;
    player.stackCents = buyInCents;
    player.roundBetCents = 0;
    player.committedCents = 0;
    player.needsAction = false;
    player.sittingOutUntilNextHand = this.deps.state.street !== "WAITING";

    this.deps.state.playersById.set(botId, player);
    this.deps.state.seats[seat] = botId;
    if (this.deps.state.street !== "WAITING" && this.deps.state.initialChipMassCents > 0) {
      this.deps.state.initialChipMassCents += buyInCents;
    }

    this.ensureToActHasNeedsActionIfNeeded(seat, botId);

    if (this.deps.persistence.enabled && this.deps.persistence.handHistory) {
      const roster = [...this.deps.state.playersById.values()]
        .filter((pl) => pl.seat >= 0)
        .map((pl) => ({
          id: pl.id,
          name: pl.name,
          seat: pl.seat,
          userId: pl.kind === "HUMAN" ? pl.userId || pl.id : null,
        }));
      await this.deps.persistence.handHistory.ensureTableAndPlayers(roster);
    }

    plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });
    plans.push({ kind: "MAYBE_AUTOMATE_TURN" });

    logger.info({ botId, seat }, "bot joined");
    if (countNonOutPlayers(this.deps.state) >= 2 && this.deps.state.street === "WAITING") {
      plans.push({ kind: "START_HAND" });
    } else {
      if (this.deps.state.street !== "WAITING") {
        player.status = "ABANDONED";
      }
      player.sittingOutUntilNextHand = true;
    }
    maybeAssertStateInvariants(this.deps.state);
    return plans;
  }

  async removeBot(botId: string): Promise<PlayerLifecyclePlan[]> {
    const plans: PlayerLifecyclePlan[] = [];
    let player = this.deps.state.playersById.get(botId);
    if (!player) return plans;

    const canRemoveDuringHand =
      player.status === "ABANDONED" ||
      player.status === "OUT" ||
      player.sittingOutUntilNextHand ||
      player.stackCents === 0;
    if (this.deps.state.street !== "WAITING" && !canRemoveDuringHand) {
      this.deferRemovalDuringActiveHand(player, "BOT_AUTO_REMOVE", plans);
      return plans;
    }

    const seat = player.seat;
    if (this.shouldForceFold(player) && this.deps.forceFoldIfInHand) {
      await this.deps.forceFoldIfInHand(botId);
      player = this.deps.state.playersById.get(botId);
      if (!player) return plans;
    }

    this.deps.pendingSeatReleaseUserIds.delete(botId);
    this.deps.autoActionsByUserId.delete(botId);
    this.deps.currentHandAutoActedUserIds.delete(botId);

    this.deps.state.seats[player.seat] = "";
    this.deps.state.playersById.delete(botId);
    this.deps.getHoleCardsByPlayerId().delete(botId);
    this.syncBettingStateAfterRemoval();
    if (this.deps.persistence.enabled && typeof this.deps.persistence.handHistory?.removePlayer === "function") {
      await this.deps.persistence.handHistory.removePlayer(botId);
    }
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });

    logger.info({ botId }, "bot left");
    plans.push({ kind: "ENSURE_HAND_ADVANCING_AFTER_PLAYER_REMOVAL", removedSeat: seat });
    maybeAssertStateInvariants(this.deps.state);
    return plans;
  }

  /**
   * Remove a player from the table with optional cash-out
   * 
   * PROCESS:
   * 1. Check for duplicate removal/cash-out operations
   * 2. Handle cash-out through cashier service if requested
   * 3. Remove player from table and update state
   * 4. Handle hand advancement if player was in current hand
   * 5. Generate appropriate lifecycle plans
   * 
   * CONCURRENCY SAFETY:
   * - Prevents duplicate removal through tracking sets
   * - Handles hand state transitions consistently
   * 
   * @param userId Unique player identifier
   * @param options Optional cash-out configuration
   * @returns Array of lifecycle plans for player removal
   */
  async removePlayer(userId: string, options?: { cashOutAfterRemoval?: boolean }): Promise<PlayerLifecyclePlan[]> {
    const plans: PlayerLifecyclePlan[] = [];
    if (this.cashedOutUserIds.has(userId)) {
      logger.warn({ userId }, "Duplicate remove/leave prevented (already cashed out)");
      return plans;
    }
    if (this.leaveInProgressUserIds.has(userId)) {
      logger.warn({ userId }, "Duplicate remove/leave prevented (leave already in progress)");
      return plans;
    }
    this.leaveInProgressUserIds.add(userId);
    try {
      let player = this.deps.state.playersById.get(userId);
      if (!player) return plans;

      if (this.deps.state.street !== "WAITING") {
        this.deferRemovalDuringActiveHand(player, "LEAVE", plans);
        return plans;
      }

      const seat = player.seat;
      if (this.shouldForceFold(player) && this.deps.forceFoldIfInHand) {
        await this.deps.forceFoldIfInHand(userId);
        player = this.deps.state.playersById.get(userId);
        if (!player) return plans;
      }

      const remainingStack = player.stackCents;
      if (!options?.cashOutAfterRemoval) {
        await this.cashOutRemainingStack(userId, remainingStack);
      }

      this.deps.pendingSeatReleaseUserIds.delete(userId);
      this.deps.autoActionsByUserId.delete(userId);
      this.deps.currentHandAutoActedUserIds.delete(userId);

      this.deps.state.seats[player.seat] = "";
      this.deps.state.playersById.delete(userId);
      this.deps.getHoleCardsByPlayerId().delete(userId);
      this.syncBettingStateAfterRemoval();
      if (this.deps.persistence.enabled && typeof this.deps.persistence.handHistory?.removePlayer === "function") {
        await this.deps.persistence.handHistory.removePlayer(userId);
      }
      plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });

      logger.info({ userId }, "player left");
      plans.push({ kind: "ENSURE_HAND_ADVANCING_AFTER_PLAYER_REMOVAL", removedSeat: seat });

      if (options?.cashOutAfterRemoval) {
        await this.cashOutRemainingStack(userId, remainingStack);
      }
      maybeAssertStateInvariants(this.deps.state);
      return plans;
    } finally {
      this.leaveInProgressUserIds.delete(userId);
    }
  }

  // ============================================================================
  // CONNECTION MANAGEMENT METHODS
  // ============================================================================

  /**
   * Mark a player as disconnected with deadline
   * 
   * PROCESS:
   * 1. Update player connection state and deadline
   * 2. Generate snapshot and automation plans
   * 3. Validate state invariants
   * 
   * @param userId Unique player identifier
   * @param disconnectDeadlineTs Timestamp when disconnection becomes final
   * @returns Array of lifecycle plans for disconnection
   */
  markDisconnected(userId: string, disconnectDeadlineTs: number): PlayerLifecyclePlan[] {
    const plans: PlayerLifecyclePlan[] = [];
    const player = this.deps.state.playersById.get(userId);
    if (!player) return plans;

    player.connected = false;
    player.disconnectDeadlineTs = disconnectDeadlineTs;
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });
    plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    maybeAssertStateInvariants(this.deps.state);
    return plans;
  }

  markReconnected(userId: string): PlayerLifecyclePlan[] {
    const plans: PlayerLifecyclePlan[] = [];
    const player = this.deps.state.playersById.get(userId);
    if (!player) return plans;

    player.connected = true;
    if (player.status === "ABANDONED" && player.stackCents > 0 && this.deps.state.street === "WAITING") {
      player.status = "ACTIVE";
    }
    player.disconnectDeadlineTs = 0;
    this.deps.autoActionsByUserId.delete(userId);
    this.ensureToActHasNeedsActionIfNeeded(player.seat, userId);
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "RECONNECT" });
    plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    maybeAssertStateInvariants(this.deps.state);
    return plans;
  }

  async markAbandoned(userId: string): Promise<PlayerLifecyclePlan[]> {
    const plans: PlayerLifecyclePlan[] = [];
    let player = this.deps.state.playersById.get(userId);
    if (!player) return plans;
    const nowTs = Date.now();

    if (this.shouldForceFold(player) && this.deps.forceFoldIfInHand) {
      await this.deps.forceFoldIfInHand(userId);
      player = this.deps.state.playersById.get(userId);
      if (!player) return plans;
    }

    player.connected = false;
    // Preserve a still-active disconnect deadline so seat release can be guarded
    // until reconnect grace expires.
    if (!(player.disconnectDeadlineTs > 0 && nowTs <= player.disconnectDeadlineTs)) {
      player.disconnectDeadlineTs = 0;
    }
    player.status = "ABANDONED";
    player.needsAction = false;
    player.pendingLeave = true;
    player.pendingRemovalReason = "DISCONNECT_TIMEOUT";
    this.deps.pendingSeatReleaseUserIds.add(userId);
    plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });

    if (this.deps.state.street === "WAITING") {
      plans.push({ kind: "RELEASE_PENDING_SEATS" });
      maybeAssertStateInvariants(this.deps.state);
      return plans;
    }

    if (countNotFoldedPlayers(this.deps.state) <= 1) {
      plans.push({ kind: "FINISH_HAND_BY_LAST_STANDING" });
      maybeAssertStateInvariants(this.deps.state);
      return plans;
    }

    if (this.deps.state.toActSeat === player.seat) {
      if (bettingRoundComplete(this.deps.state) || noFurtherBettingPossible(this.deps.state)) {
        plans.push({ kind: "ADVANCE_STREET_OR_SHOWDOWN" });
      } else {
        const nextSeat = findNextToActSeat(this.deps.state, player.seat);
        if (nextSeat === -1) {
          plans.push({ kind: "ADVANCE_STREET_OR_SHOWDOWN" });
          maybeAssertStateInvariants(this.deps.state);
          return plans;
        }
        this.deps.state.toActSeat = nextSeat;
        plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
      }
    } else {
      plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    }
    maybeAssertStateInvariants(this.deps.state);
    return plans;
  }

  // ============================================================================
  // HELPER & UTILITY METHODS
  // ============================================================================

  /**
   * Determine if player should be force-folded before removal
   * 
   * LOGIC:
   * Player must be ACTIVE and hand must be in progress
   * This ensures hand history and pot calculations remain consistent
   * 
   * @param player Player state to evaluate
   * @returns True if force-fold should be applied
   */
  private shouldForceFold(player: PlayerState): boolean {
    return this.deps.state.street !== "WAITING" && player.status === "ACTIVE";
  }

  private deferRemovalDuringActiveHand(
    player: PlayerState,
    reason: "LEAVE" | "DISCONNECT_TIMEOUT" | "BOT_AUTO_REMOVE",
    plans: PlayerLifecyclePlan[],
  ): void {
    const nowTs = Date.now();
    const hasActiveDisconnectProtection =
      player.disconnectDeadlineTs > 0 && nowTs <= player.disconnectDeadlineTs;

    player.connected = false;
    if (reason !== "DISCONNECT_TIMEOUT" && !hasActiveDisconnectProtection) {
      player.disconnectDeadlineTs = 0;
    }
    player.status = "ABANDONED";
    player.needsAction = false;
    player.pendingLeave = true;
    player.pendingRemovalReason = reason;
    this.deps.pendingSeatReleaseUserIds.add(player.id);
    this.deps.autoActionsByUserId.delete(player.id);
    this.deps.currentHandAutoActedUserIds.delete(player.id);
    this.syncBettingStateAfterRemoval();

    plans.push({ kind: "EMIT_SNAPSHOT", reason: "SEAT_CHANGE" });
    plans.push({ kind: "LIFECYCLE_DEFERRED_REMOVAL", userId: player.id, reason });

    if (countNotFoldedPlayers(this.deps.state) <= 1) {
      plans.push({ kind: "FINISH_HAND_BY_LAST_STANDING" });
      maybeAssertStateInvariants(this.deps.state);
      return;
    }

    if (this.deps.state.toActSeat === player.seat) {
      if (bettingRoundComplete(this.deps.state) || noFurtherBettingPossible(this.deps.state)) {
        plans.push({ kind: "ADVANCE_STREET_OR_SHOWDOWN" });
      } else {
        const nextSeat = findNextToActSeat(this.deps.state, player.seat);
        if (nextSeat === -1) {
          plans.push({ kind: "ADVANCE_STREET_OR_SHOWDOWN" });
          maybeAssertStateInvariants(this.deps.state);
          return;
        }
        this.deps.state.toActSeat = nextSeat;
        plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
      }
    } else {
      plans.push({ kind: "MAYBE_AUTOMATE_TURN" });
    }
    maybeAssertStateInvariants(this.deps.state);
  }

  /**
   * Ensure player has needsAction flag set for proper turn advancement
   * 
   * CONTEXT:
   * Called after seat changes or player restorations
   * Maintains betting round invariants when player returns to active hand
   * 
   * @param seat Seat number where player will be positioned
   * @param userId Unique player identifier
   */
  private ensureToActHasNeedsActionIfNeeded(seat: number, userId: string): void {
    const { state } = this.deps;
    if (state.street === "WAITING" || state.runoutMode === "STAGED") return;
    if (state.seats[state.toActSeat] !== userId) return;
    if (bettingRoundComplete(state) || noFurtherBettingPossible(state)) return;
    const player = state.playersById.get(userId);
    if (!player || !eligibleToAct(player)) return;
    player.needsAction = true;
  }

  /**
   * Validate buy-in amount against table limits
   * 
   * VALIDATION RULES:
   * 1. Must be positive integer
   * 2. Must meet minimum buy-in requirement
   * 3. Must not exceed maximum buy-in limit
   * 
   * @param buyInCents Amount to validate
   * @throws PokerError if validation fails
   */
  private assertValidBuyIn(buyInCents: number): void {
    if (!Number.isInteger(buyInCents) || buyInCents <= 0) {
      throw new PokerError("INVALID_BUYIN", "buyInCents must be a positive integer.");
    }
    if (buyInCents < this.deps.state.minBuyInCents) {
      throw new PokerError("INVALID_BUYIN", `buyInCents must be >= ${this.deps.state.minBuyInCents}.`);
    }
    if (buyInCents > this.deps.state.maxBuyInCents) {
      throw new PokerError("INVALID_BUYIN", `buyInCents must be <= ${this.deps.state.maxBuyInCents}.`);
    }
  }

  /**
   * Process cash-out for remaining player stack
   * 
   * PROCESS:
   * 1. Validate remaining stack amount
   * 2. Check for duplicate cash-out operations
   * 3. Process external cash-out through cashier service
   * 4. Handle errors and maintain tracking state
   * 
   * IDEMPOTENCY:
   * Uses unique external reference for transaction safety
   * 
   * @param userId Unique player identifier
   * @param remainingStack Amount to cash out
   */
  private async cashOutRemainingStack(userId: string, remainingStack: number): Promise<void> {
    if (remainingStack <= 0) return;
    if (this.cashedOutUserIds.has(userId)) {
      logger.warn({ userId }, "Duplicate cash-out prevented");
      return;
    }
    this.cashedOutUserIds.add(userId);

    const externalRef = `cashout_${this.deps.state.tableId}_${userId}_${Date.now()}_${nanoid(6)}`;
    try {
      await CashierService.processCashGameCashOut({
        userId,
        tableId: this.deps.state.tableId,
        amountCents: remainingStack,
        externalRef,
        tableMeta: {
          name: this.deps.state.tableName,
        },
      });
      logger.info({ userId, remainingStack }, "cash-out processed");
    } catch (err: unknown) {
      this.cashedOutUserIds.delete(userId);
      logger.error({ userId, err }, "cash-out failed, funds may be locked in PlayerBalance");
    }
  }

  /**
   * Synchronize betting state after player removal to maintain consistency
   * 
   * PURPOSE:
   * Ensures roundCurrentBetCents never exceeds any player's roundBetCents
   * Prevents chip inflation and maintains betting round integrity
   */
  private syncBettingStateAfterRemoval(): void {
    if (this.deps.state.street === "WAITING") {
      // In WAITING we only need monotonic safety: roundCurrentBet must never exceed any seat roundBet.
      let maxRoundBet = 0;
      for (const p of this.deps.state.playersById.values()) {
        maxRoundBet = Math.max(maxRoundBet, p.roundBetCents);
      }
      this.deps.state.roundCurrentBetCents = maxRoundBet;
      return;
    }
    syncRoundCurrentBetCents(this.deps.state);
  }
}

/**
 * SnapshotService - Game State Snapshots & Client Notifications
 * 
 * PURPOSE:
 * Manages game state snapshots and real-time client notifications.
 * Handles snapshot creation, validation, broadcasting, and persistence.
 * Integrates with hand calculations and replay system.
 * 
 * KEY RESPONSIBILITIES:
 * - Create and validate game state snapshots
 * - Broadcast snapshots to connected clients
 * - Calculate hand odds and statistics
 * - Manage snapshot sequencing and versioning
 * - Provide hooks for custom snapshot processing
 * 
 * CLIENT COMMUNICATION:
 * - Uses Colyseus for real-time message broadcasting
 * - Maintains client connection state
 * - Handles message validation and routing
 * 
 * USAGE:
 * const service = new SnapshotService(dependencies);
 * await service.emitToAll("HAND_START");
 * // Snapshots are broadcast to all connected clients
 * 
 */

// ============================================================================
// IMPORTS - External Dependencies
// ============================================================================
import { Client } from "@colyseus/core";
import { createHash } from "node:crypto";

// ============================================================================
// IMPORTS - Internal Dependencies
// ============================================================================
import { logger } from "../../../lib/logger.js";
import type { PokerState } from "../../../state/PokerState.js";
import { HandCalculationsCoordinator } from "../../odds/HandCalculationsCoordinator.js";
import { toFrameReason, type FrameReason } from "../../replay/FrameReason.js";

// ============================================================================
// IMPORTS - Metrics & Monitoring
// ============================================================================
import { snapshotMetrics } from "../metrics/snapshotMetrics.js";

// ============================================================================
// IMPORTS - Type Definitions
// ============================================================================
import { TableOutboundMessageSchema, type HeroActionOptions, type TableSnapshotPayload } from "@poker-champ/realtime-contract";

// ============================================================================
// TYPE DEFINITIONS & CONSTANTS
// ============================================================================

/**
 * Snapshot emission hook for custom processing
 * Allows external systems to intercept and process snapshots
 * before they are broadcast to clients.
 */
export type SnapshotEmitHook = (args: {
  tableId: string;
  handId?: string;
  snapshotId: string;
  reason: SnapshotReason;
  frameReason?: FrameReason;
  street: string;
  payloadJson: TableSnapshotPayload;
  stateHash: string;
  schemaVersion: number;
}) => Promise<void> | void;

/**
 * Snapshot reason type alias for cleaner imports
 */
export type SnapshotReason = TableSnapshotPayload["reason"];

/** Schema version for ERROR payloads; must match realtime-contract. */
const ERROR_PAYLOAD_VERSION = 1;

/** User-facing message when snapshot validation fails; client can show Retry/Leave. */
const SNAPSHOT_INVALID_MESSAGE =
  "Table failed to load due to a server error. Please try again or leave the table.";

/** Max wait for avatar fetch so snapshot emission never blocks the action queue. */
const AVATAR_FETCH_TIMEOUT_MS = 2000;

/** One-line searchable first failing path from Zod error (e.g. "payload.snapshotSeq"). */
function getFirstFailingPath(err: { issues?: Array<{ path?: PropertyKey[] }> }): string | null {
  const first = err.issues?.[0];
  if (!first?.path?.length) return null;
  return first.path.map((segment) => String(segment)).join(".");
}

// ============================================================================
// MAIN CLASS - Snapshot Management & Broadcasting
// ============================================================================

/**
 * SnapshotService - Core service for managing game state snapshots
 * 
 * This class handles the creation, validation, and broadcasting of game
 * state snapshots to connected clients. It integrates with the hand
 * calculation system and provides hooks for custom snapshot processing.
 * 
 * CLIENT INTEGRATION:
 * - Uses Colyseus for real-time message broadcasting
 * - Maintains client connection state and message routing
 * - Validates outbound messages against schemas
 * 
 * SNAPSHOTS:
 * - Creates comprehensive game state snapshots
 * - Includes hand calculations, odds, and statistics
 * - Sequences and versions snapshots for replay
 * 
 * USAGE:
 * const service = new SnapshotService(dependencies);
 * await service.emitToAll("HAND_START");
 * // Snapshots are broadcast to all connected clients
 */
export class SnapshotService {
  // ============================================================================
  // CLASS PROPERTIES - State Management & Tracking
  // ============================================================================
  
  /** Hand calculations coordinator for odds and statistics */
  private readonly handCalculations = new HandCalculationsCoordinator();
  /** Global snapshot sequence counter (shared by broadcast and user-targeted snapshots; contract requires positive) */
  private snapshotSeq = 0;
  /** Last hand key for detecting hand changes */
  private lastHandKey: string | null = null;

  /**
   * Fetch avatar with timeout so slow or stuck avatar lookup never blocks the game loop.
   * Returns nulls on timeout or throw.
   */
  private async getAvatarWithTimeout(userId: string): Promise<{ avatarUrl: string | null; avatarVersion: number | null }> {
    const getAvatar = this.deps.getAvatarByUserId;
    if (!getAvatar) return { avatarUrl: null, avatarVersion: null };
    const fallback = (): { avatarUrl: string | null; avatarVersion: number | null } =>
      ({ avatarUrl: null, avatarVersion: null });
    try {
      const result = await Promise.race([
        getAvatar(userId),
        new Promise<{ avatarUrl: string | null; avatarVersion: number | null }>((resolve) =>
          setTimeout(() => resolve(fallback()), AVATAR_FETCH_TIMEOUT_MS),
        ),
      ]);
      return result ?? fallback();
    } catch {
      return fallback();
    }
  }

  // ============================================================================
  // CONSTRUCTOR & DEPENDENCIES
  // ============================================================================
  
  /**
   * Initialize SnapshotService with required dependencies
   * @param deps - Service dependencies for state, clients, and data access
   */
  constructor(private readonly deps: {
    state: PokerState;
    clientsByUserId: Map<string, Client>;
    getHoleCardsByPlayerId: () => Map<string, string[]>;
    getHeroActionOptions: (userId: string) => HeroActionOptions | undefined;
    getLastHandResult: () => TableSnapshotPayload["lastHandResult"] | undefined;
    getLastAction: () => TableSnapshotPayload["lastAction"] | undefined;
    getHeroSessionStats?: (userId: string) => TableSnapshotPayload["hero"]["playerStats"];
    /** Optional hook for custom snapshot processing */
    emitHook?: SnapshotEmitHook;
    /** Optional: fetch avatar for snapshot seat/hero. When provided, seats and hero include avatarUrl/avatarVersion. */
    getAvatarByUserId?: (userId: string) => Promise<{ avatarUrl: string | null; avatarVersion: number | null }>;
  }) {}

  // ============================================================================
  // SNAPSHOT BROADCASTING METHODS
  // ============================================================================

  /**
   * Emit snapshot to all connected clients
   * 
   * PROCESS:
   * 1. Generate unique snapshot sequence number
   * 2. Refresh hand calculations if needed
   * 3. Build comprehensive snapshot payload
   * 4. Determine current acting player for context
   * 5. Validate snapshot integrity (development mode)
   * 6. Apply custom emit hook if provided
   * 7. Broadcast to all clients via Colyseus
   * 8. Record metrics for monitoring
   * 
   * BROADCASTING:
   * - Uses Colyseus room broadcast for efficiency
   * - Validates message schema before sending
   * - Handles connection state management
   * 
   * @param reason Snapshot reason for context
   * @param actionId Optional action identifier
   * @returns void - Async broadcast operation
   */
  /** When set, this recipient is sent the snapshot first even if not in clientsByUserId (avoids missing update if client was unbound during async build). */
  async emitToAll(
    reason: SnapshotReason,
    actionId?: string,
    ensureRecipient?: { userId: string; client: Client },
  ): Promise<void> {
    const t0 = performance.now();
    const snapshotSeq = this.nextSnapshotSeq();
    this.refreshHandCalculationsIfNeeded();
    const base = await this.buildBaseSnapshot(reason, actionId, snapshotSeq);
    const toActUserId = this.deps.state.street !== "WAITING"
      ? (this.deps.state.seats[this.deps.state.toActSeat] ?? null)
      : null;

    const systemPayload = this.finalizePayload(await this.buildHeroPatch("SYSTEM", base, toActUserId), "SYSTEM");
    this.emitSnapshotHook(systemPayload, reason);

    const tableId = this.deps.state.tableId;
    const sendToOne = async (userId: string, client: Client): Promise<boolean> => {
      const payload = await this.buildHeroPatch(userId, base, toActUserId);
      const final = this.finalizePayload(payload, userId);
      const parsed = TableOutboundMessageSchema.safeParse({ type: "TABLE_SNAPSHOT", payload: final });
      if (!parsed.success) {
        const path = getFirstFailingPath(parsed.error);
        logger.warn(
          { reason, userId, tableId, snapshotSeq, path, errors: parsed.error.flatten() },
          "SNAPSHOT_DROP tableId=%s userId=%s reason=%s path=%s",
          tableId,
          userId,
          reason,
          path ?? "unknown",
        );
        client.send("ERROR", {
          version: ERROR_PAYLOAD_VERSION,
          code: "SNAPSHOT_INVALID",
          message: SNAPSHOT_INVALID_MESSAGE,
        });
        return false;
      }
      try {
        client.send("TABLE_SNAPSHOT", final);
        snapshotMetrics.emitSnapshot();
        return true;
      } catch (err) {
        logger.warn({ err, userId, tableId, reason }, "SNAPSHOT_SEND_FAILED ensureRecipient");
        return false;
      }
    };

    if (ensureRecipient) {
      await sendToOne(ensureRecipient.userId, ensureRecipient.client);
    }
    for (const [userId, client] of this.deps.clientsByUserId.entries()) {
      if (ensureRecipient && userId === ensureRecipient.userId) continue;
      await sendToOne(userId, client);
    }
    snapshotMetrics.observeBuildMs(performance.now() - t0);
  }

  async emitToUser(userId: string, reason: SnapshotReason, actionId?: string): Promise<void> {
    const client = this.deps.clientsByUserId.get(userId);
    if (!client) return;

    const t0 = performance.now();
    const snapshotSeq = this.nextSnapshotSeq();
    this.refreshHandCalculationsIfNeeded();
    const base = await this.buildBaseSnapshot(reason, actionId, snapshotSeq);
    const toActUserId = this.deps.state.street !== "WAITING"
      ? (this.deps.state.seats[this.deps.state.toActSeat] ?? null)
      : null;
    const payload = await this.buildHeroPatch(userId, base, toActUserId);
    const final = this.finalizePayload(payload, userId);

    const parsed = TableOutboundMessageSchema.safeParse({ type: "TABLE_SNAPSHOT", payload: final });
    if (!parsed.success) {
      const tableId = this.deps.state.tableId;
      const path = getFirstFailingPath(parsed.error);
      logger.warn(
        { reason, userId, tableId, snapshotSeq, path, errors: parsed.error.flatten() },
        "SNAPSHOT_DROP tableId=%s userId=%s reason=%s path=%s",
        tableId,
        userId,
        reason,
        path ?? "unknown",
      );
      client.send("ERROR", {
        version: ERROR_PAYLOAD_VERSION,
        code: "SNAPSHOT_INVALID",
        message: SNAPSHOT_INVALID_MESSAGE,
      });
      return;
    }
    client.send("TABLE_SNAPSHOT", final);
    snapshotMetrics.emitSnapshot();

    const systemPayload = this.finalizePayload(await this.buildHeroPatch("SYSTEM", base, toActUserId), "SYSTEM");
    this.emitSnapshotHook(systemPayload, reason);
    snapshotMetrics.observeBuildMs(performance.now() - t0);
  }

  private emitSnapshotHook(payload: TableSnapshotPayload, reason: SnapshotReason): void {
    const callback = this.deps.emitHook;
    if (!callback) return;

    const state = this.deps.state;
    void Promise.resolve(callback({
      tableId: state.tableId,
      handId: state.handId || undefined,
      snapshotId: payload.snapshotId,
      reason,
      frameReason: toFrameReason(reason) ?? undefined,
      street: payload.hand?.street ?? "WAITING",
      payloadJson: payload,
      stateHash: payload.stateHash,
      schemaVersion: payload.version,
    })).catch((err) => {
      logger.warn({ err, tableId: state.tableId, snapshotId: payload.snapshotId }, "TABLE_SNAPSHOT_LOG_WRITE_FAILED");
    });
  }

  private refreshHandCalculationsIfNeeded(): string | null {
    const state = this.deps.state;
    const handKey = this.buildHandCalculationKey();
    if (handKey === this.lastHandKey) return handKey;
    this.lastHandKey = handKey;
    this.updateCurrentHandCalculations();
    return handKey;
  }

  private buildHandCalculationKey(): string | null {
    const state = this.deps.state;
    if (!state.handId || state.street === "WAITING") return null;

    const boardKey = state.board.join(",");
    const playersKey = [...state.playersById.values()]
      .sort((a, b) => a.seat - b.seat)
      .map((p) => `${p.id}:${p.status}:${p.stackCents}:${p.roundBetCents}:${p.committedCents}`)
      .join("|");
    const holeCardsKey = [...this.deps.getHoleCardsByPlayerId().entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([id, cards]) => `${id}:${cards.join(",")}`)
      .join("|");

    return [
      state.handId,
      state.street,
      state.toActSeat,
      state.actionCount,
      state.potCents,
      state.roundCurrentBetCents,
      state.minRaiseCents,
      boardKey,
      playersKey,
      holeCardsKey,
    ].join("_");
  }

  private updateCurrentHandCalculations(): void {
    const state = this.deps.state;
    this.handCalculations.refresh({
      tableId: state.tableId,
      handId: state.handId,
      street: state.street,
      board: [...state.board],
      potCents: state.potCents,
      roundCurrentBetCents: state.roundCurrentBetCents,
      minRaiseCents: state.minRaiseCents,
      toActSeat: state.toActSeat,
      players: [...state.playersById.values()].map((player) => ({
        id: player.id,
        seat: player.seat,
        status: player.status,
        stackCents: player.stackCents,
        roundBetCents: player.roundBetCents,
        committedCents: player.committedCents,
      })),
      holeCardsByPlayerId: this.deps.getHoleCardsByPlayerId(),
      getActionOptions: (userId) => this.deps.getHeroActionOptions(userId),
    });
  }

  // ============================================================================
  // HELPER & UTILITY METHODS
  // ============================================================================

  /**
   * Generate next snapshot sequence number
   * 
   * PURPOSE:
   * Provides sequential numbering for snapshots
   * Handles bootstrap scenario for proper initialization
   * 
   * @returns Next snapshot sequence number
   */
  private nextSnapshotSeq(): number {
    this.snapshotSeq += 1;
    return this.snapshotSeq;
  }

  /**
   * Get current snapshot sequence number
   * 
   * PURPOSE:
   * Returns the current snapshot sequence for validation
   * Ensures sequence starts at 1 after bootstrap
   * 
   * @returns Current snapshot sequence number
   */
  private currentSnapshotSeq(): number {
    if (this.snapshotSeq <= 0) {
      logger.warn({ tableId: this.deps.state.tableId, reason: "bootstrap" }, "TABLE_SNAPSHOT_SEQ_BOOTSTRAP_TO_ONE");
      return 1;
    }
    return this.snapshotSeq;
  }

  /**
   * Build base snapshot payload with common fields
   * 
   * PROCESS:
   * 1. Capture current game state and metadata
   * 2. Include table configuration and player states
   * 3. Add timing and sequence information
   * 4. Generate state hash for integrity validation
   * 
   * @param reason Snapshot reason for context
   * @param actionId Optional action identifier
   * @param snapshotSeq Unique sequence number
   * @returns Base snapshot payload object
   */
  private async buildBaseSnapshot(
    reason: SnapshotReason,
    actionId: string | undefined,
    snapshotSeq: number,
  ): Promise<Omit<TableSnapshotPayload, "hero" | "stateHash">> {
    const state = this.deps.state;
    const nowTs = Date.now();

    const seats = await Promise.all(
      state.seats.map(async (occupantUserId, seat) => {
        const player = occupantUserId ? state.playersById.get(occupantUserId) : undefined;
        const connected = player?.connected ?? false;
        const disconnectDeadlineTs = player?.disconnectDeadlineTs ?? 0;
        if (connected && disconnectDeadlineTs !== 0) {
          logger.error({ tableId: state.tableId, seat, playerId: player?.id }, "INVARIANT: connected player must have disconnectDeadlineTs 0");
          throw new Error("INVARIANT_VIOLATION");
        }
        let avatarUrl: string | undefined;
        let avatarVersion: number | undefined;
        if (occupantUserId && player?.kind === "HUMAN") {
          const av = await this.getAvatarWithTimeout(occupantUserId);
          if (av.avatarUrl) avatarUrl = av.avatarUrl;
          if (av.avatarVersion != null) avatarVersion = av.avatarVersion;
        }
        return {
          seat,
          occupied: Boolean(player),
          userId: player?.id,
          isBot: player?.kind === "BOT",
          name: player?.name || "Empty",
          status: player?.status ?? "OUT",
          stackCents: player?.stackCents ?? 0,
          roundBetCents: player?.roundBetCents ?? 0,
          committedCents: player?.committedCents ?? 0,
          connected,
          disconnectDeadlineTs,
          isDealer: state.dealerSeat === seat,
          isToAct: state.toActSeat === seat,
          ...(avatarUrl != null && { avatarUrl }),
          ...(avatarVersion != null && { avatarVersion }),
        };
      }),
    );

    const hand = state.street === "WAITING"
      ? undefined
      : {
          handId: state.handId,
          handNumber: state.handNumber,
          street: state.street,
          dealerSeat: state.dealerSeat,
          sbSeat: state.sbSeat,
          bbSeat: state.bbSeat,
          toActSeat: state.toActSeat,
          actionCount: state.actionCount,
          roundCurrentBetCents: state.roundCurrentBetCents,
          minRaiseCents: state.minRaiseCents,
          potCents: state.potCents,
          board: [...state.board],
        };

    return {
      version: 1 as const,
      snapshotId: `snap_${state.tableId}_${snapshotSeq}`,
      snapshotSeq,
      emittedAtTs: nowTs,
      serverTimeTs: nowTs,
      reason,
      actionId,
      nextHandAtTs: state.nextHandAtTs || undefined,
      table: {
        tableId: state.tableId,
        tableName: state.tableName,
        ...(state.creatorId ? { creatorId: state.creatorId } : {}),
        visibility: state.visibility,
        maxSeats: state.maxSeats,
        smallBlindCents: state.smallBlindCents,
        bigBlindCents: state.bigBlindCents,
        minBuyInCents: state.minBuyInCents,
        maxBuyInCents: state.maxBuyInCents,
        showStats: state.showStats,
      },
      hand,
      seats,
      calculationsMeta: this.handCalculations.getMeta(),
      lastAction: this.deps.getLastAction(),
      lastHandResult: this.deps.getLastHandResult(),
    };
  }

  private async buildHeroPatch(
    userId: string,
    base: Omit<TableSnapshotPayload, "hero" | "stateHash">,
    toActUserId: string | null,
  ): Promise<Omit<TableSnapshotPayload, "stateHash">> {
    const state = this.deps.state;
    const hero = state.playersById.get(userId);
    const liveHoleCards = hero ? this.deps.getHoleCardsByPlayerId().get(userId) : undefined;
    const revealedShowdownHoleCards =
      hero && state.street === "WAITING"
        ? this.deps.getLastHandResult()?.showdownHoleCardsByUserId?.[userId]
        : undefined;
    const heroHoleCards = liveHoleCards ?? (revealedShowdownHoleCards ? [...revealedShowdownHoleCards] : undefined);
    const actionOptions = userId === toActUserId ? this.deps.getHeroActionOptions(userId) : undefined;
    const calc = this.handCalculations.getForUser(userId);
    const callAmount = actionOptions?.callAmount ?? 0;
    const potOddsPct = callAmount > 0
      ? Math.round((callAmount / (state.potCents + callAmount)) * 100)
      : undefined;

    let avatarUrl: string | undefined;
    let avatarVersion: number | undefined;
    const av = await this.getAvatarWithTimeout(userId);
    if (av.avatarUrl) avatarUrl = av.avatarUrl;
    if (av.avatarVersion != null) avatarVersion = av.avatarVersion;

    const hasCalc = Boolean(calc) || potOddsPct !== undefined;
    const heroSection = {
      userId,
      youAreSeated: Boolean(hero),
      seat: hero?.seat,
      holeCards: hero ? heroHoleCards : undefined,
      actionOptions,
      calculations: hasCalc
        ? {
            mode: (calc?.mode ?? "SHOWDOWN_ANALYSIS") as "LIVE_ADVISORY" | "SHOWDOWN_ANALYSIS",
            stale: calc?.stale ?? false,
            equityPct: calc?.equityPct,
            potOddsPct: calc?.potOddsPct ?? potOddsPct,
            outs: calc?.outs,
            updatedAtTs: calc?.updatedAtTs,
          }
        : undefined,
      playerStats: this.deps.getHeroSessionStats?.(userId),
      ...(avatarUrl != null && { avatarUrl }),
      ...(avatarVersion != null && { avatarVersion }),
    };

    return { ...base, hero: heroSection };
  }

  private finalizePayload(payload: Omit<TableSnapshotPayload, "stateHash">, _userId: string): TableSnapshotPayload {
    const stateHash = createHash("sha1").update(JSON.stringify(payload)).digest("hex");
    return { ...payload, stateHash };
  }
}

import { describe, expect, it } from "vitest";
import { HandLifecycleService } from "./HandLifecycleService.js";
import type { PlayerState } from "../../../state/PlayerState.js";
import { PlayerState as PlayerStateClass } from "../../../state/PlayerState.js";
import { PokerState } from "../../../state/PokerState.js";

function makePlayer(input: {
  id: string;
  seat: number;
  committedCents: number;
  stackCents?: number;
  status?: PlayerState["status"];
}): PlayerState {
  const p = new PlayerStateClass();
  p.id = input.id;
  p.userId = input.id;
  p.kind = "HUMAN";
  p.name = input.id;
  p.seat = input.seat;
  p.status = input.status ?? "ALL_IN";
  p.stackCents = input.stackCents ?? 0;
  p.roundBetCents = input.committedCents;
  p.committedCents = input.committedCents;
  p.needsAction = false;
  p.connected = true;
  return p;
}

function makeHarness() {
  const state = new PokerState();
  state.tableId = "table_showdown";
  state.street = "SHOWDOWN";
  state.runoutMode = "STAGED";
  state.handId = "hand_showdown";
  state.dealerSeat = 0;

  const holeCardsByPlayerId = new Map<string, string[]>();
  const handStartingStacksByPlayerId = new Map<string, number>();
  const processedActionIds = new Set<string>();
  const currentHandAutoActedUserIds = new Set<string>();
  const payoutCalls: Array<{ id: string; amount: number }> = [];
  let lastHandResult: Record<string, unknown> | undefined;
  let disbursedCents = 0;

  const service = new HandLifecycleService({
    state,
    persistence: {
      enabled: false,
      assertHandBalanced: async () => {},
    } as any,
    settlementService: {
      creditPayoutToPlayer: async (player: PlayerState, amountCents: number) => {
        player.stackCents += amountCents;
        disbursedCents += amountCents;
        payoutCalls.push({ id: player.id, amount: amountCents });
      },
      finalizePersistedHand: async () => {},
      getCurrentHandPotDisbursedCents: () => disbursedCents,
    } as any,
    getHoleCardsByPlayerId: () => holeCardsByPlayerId,
    getHandStartingStacksByPlayerId: () => handStartingStacksByPlayerId,
    currentHandAutoActedUserIds,
    getProcessedActionIds: () => processedActionIds,
    applyDisconnectedAutoActionCapForHand: async () => {},
    setLastHandResult: (value) => {
      lastHandResult = value as Record<string, unknown>;
    },
    setLastAction: () => {},
  });

  return {
    service,
    state,
    holeCardsByPlayerId,
    payoutCalls,
    getLastHandResult: () => lastHandResult,
  };
}

function sumStacks(players: PlayerState[]): number {
  return players.reduce((s, p) => s + p.stackCents, 0);
}

/** S4 — Chip conservation: after payouts, sum(stacks) === pre-hand total (all chips accounted for). */
function assertChipConservation(
  playersBefore: PlayerState[],
  potCents: number,
  playersAfter: PlayerState[],
): void {
  const preTotal = sumStacks(playersBefore) + potCents;
  const postTotal = sumStacks(playersAfter);
  expect(postTotal).toBe(preTotal);
}

