import { logger } from "../../lib/logger.js";
import { PokerRoomAuthAdapter } from "./PokerRoomAuthAdapter.js";
import { PokerRoomJoinService } from "./PokerRoomJoinService.js";
import { PokerRoomLeaveService } from "./PokerRoomLeaveService.js";
import { PokerRoomLifecycle } from "./PokerRoomLifecycle.js";
import { PokerRoomMessageRouter } from "./PokerRoomMessageRouter.js";
import { PokerRoomSessionManager } from "./PokerRoomSessionManager.js";
import { PokerRoomBotService } from "./features/PokerRoomBotService.js";
import { PokerRoomIdleManager } from "./features/PokerRoomIdleManager.js";
import { PokerRoomPresence } from "./features/PokerRoomPresence.js";
import { PokerRoomSeatRecovery } from "./features/PokerRoomSeatRecovery.js";
import { PokerRoomStallMonitor } from "./features/PokerRoomStallMonitor.js";
import { registerVoiceRelay } from "../voice/register-voice-relay.js";
import type { PokerRoomContext, PokerRoomFacade } from "./types/PokerRoomTypes.js";

export class PokerRoomController {
  readonly context: PokerRoomContext;
  readonly session: PokerRoomSessionManager;
  readonly auth: PokerRoomAuthAdapter;
  readonly join: PokerRoomJoinService;
  readonly leave: PokerRoomLeaveService;
  readonly router: PokerRoomMessageRouter;
  readonly lifecycle: PokerRoomLifecycle;
  readonly presence: PokerRoomPresence;
  readonly idle: PokerRoomIdleManager;
  readonly seatRecovery: PokerRoomSeatRecovery;
  readonly stall: PokerRoomStallMonitor;
  readonly bots: PokerRoomBotService;

  constructor(private readonly room: PokerRoomFacade) {
    this.context = {
      room,
      roomId: room.roomId,
      get dealer() {
        return room.dealerRef;
      },
      state: room.state,
      logger,
      startStallMonitor: () => room.startStallMonitorInternal(),
      updateCreateMetadata: (cfg?: any) => room.updateCreateMetadataInternal(cfg),
      registerVoiceRelay: () => registerVoiceRelay(room),
      setSessionEventUnbind: (unbind: () => void) => room.setSessionEventUnbindInternal(unbind),
      touchActivity: () => room.touchActivityInternal(),
      bootstrapPersistentSeatRecovery: () => room.bootstrapPersistentSeatRecoveryInternal(),
      disposeRoom: () => room.disposeInternal(),
      addTablePresence: (client, userId, displayName) => room.addTablePresenceInternal(client, userId, displayName),
      removeTablePresence: (userId) => room.removeTablePresenceInternal(userId),
      handleEmptyStateChange: () => room.handleEmptyStateChangeInternal(),
      scheduleIdleDispose: () => room.scheduleIdleDisposeInternal(),
      runPersistentSeatCleanup: () => room.runPersistentSeatCleanupInternal(),
      runSittingOutSweep: (options) => room.runSittingOutSweepInternal(options),
      seedInstantBots: (presetId, targetBotCountOverride) => room.seedInstantBotsInternal(presetId, targetBotCountOverride),
      maybeRemoveBotsIfNoHumans: () => room.maybeRemoveBotsIfNoHumansInternal(),
      purgeBotsForDelete: () => room.purgeBotsForDeleteInternal(),
    };

    this.session = new PokerRoomSessionManager(this.context, {
      leaveCodeSessionReplaced: room.leaveCodeSessionReplaced,
      userIdBySessionId: room.userIdBySessionId,
      bindingEpochByUserId: room.bindingEpochByUserId,
      bindingEpochBySessionId: room.bindingEpochBySessionId,
    });
    this.auth = new PokerRoomAuthAdapter(this.context);
    this.join = new PokerRoomJoinService(this.context, this.session);
    this.leave = new PokerRoomLeaveService(this.context, this.session);
    this.router = new PokerRoomMessageRouter(this.context, this.session);
    this.lifecycle = new PokerRoomLifecycle(this.context);

    this.presence = new PokerRoomPresence(this.context);
    this.idle = new PokerRoomIdleManager(this.context);
    this.seatRecovery = new PokerRoomSeatRecovery(this.context);
    this.stall = new PokerRoomStallMonitor(this.context);
    this.bots = new PokerRoomBotService(this.context);
  }

  setupLifecycle(options?: { cfg?: any }): void {
    this.lifecycle.setup(options);
  }

  setupMessageHandlers(): void {
    this.router.registerAll();
  }
}

import { matchMaker, type Client } from "@colyseus/core";
import { TableJoinOptionsSchema } from "@poker-champ/realtime-contract";
import type { ZodIssue } from "zod";
import { PokerError } from "../../engine/errors.js";
import { TableSeatSessionService } from "../../engine/seats/TableSeatSessionService.js";
import { presenceIndex } from "../../lobby/PresenceIndex.js";
import type { PokerRoomSessionManager } from "./PokerRoomSessionManager.js";
import type { PokerRoomContext, PokerRoomJoinServiceContract } from "./types/PokerRoomTypes.js";

export class PokerRoomJoinService implements PokerRoomJoinServiceContract {
  constructor(
    private readonly ctx: PokerRoomContext,
    private readonly session: PokerRoomSessionManager,
  ) {}

  async handleJoin(client: Client, options: any, auth?: any): Promise<void> {
    const room = this.ctx.room;
    const userId = auth?.userId;
    const requestedBuyInCents =
      Number.isInteger(options?.buyInCents) && (options?.buyInCents as number) > 0
        ? (options!.buyInCents as number)
        : null;

    const lockKey = `${this.ctx.state.tableId}:${userId ?? client.sessionId}`;
    await room.withJoinLockInternal(lockKey, async () => {
      if (room.isDeletingInternal) {
        room.sendTableMessageInternal(client, "ERROR", { code: "TABLE_GONE", message: "Table no longer exists" });
        client.leave();
        return;
      }
      room.touchActivityInternal();
      await room.runPersistentSeatCleanupInternal();

      this.ctx.logger.info(
        {
          roomId: room.roomId,
          tableId: this.ctx.state.tableId,
          sessionId: client.sessionId,
          userId,
          hasBuyIn: Number.isInteger(options?.buyInCents),
          buyInCents: options?.buyInCents,
        },
        "POKER_JOIN_ATTEMPT",
      );

      if (!userId || !auth) {
        room.sendTableMessageInternal(client, "ERROR", { code: "UNAUTHORIZED", message: "Authentication required." });
        client.leave();
        return;
      }

      const otherTableIds = presenceIndex.getTableIdsForUser(userId).filter((id) => id !== this.ctx.state.tableId);
      if (otherTableIds.length > 0) {
        type PokerRoomRef = { roomId?: string; metadata?: { tableId?: string } };
        const pokerRooms = (await matchMaker.query({ name: "poker" })) as PokerRoomRef[];
        for (const otherTableId of otherTableIds) {
          const otherRoom = pokerRooms.find((r) => r.metadata?.tableId === otherTableId);
          if (otherRoom?.roomId) {
            try {
              await matchMaker.remoteRoomCall(otherRoom.roomId, "requestUserLeaveBecauseJoiningAnotherTable" as never, [userId], 5000);
            } catch (err) {
              this.ctx.logger.warn(
                { err, roomId: room.roomId, tableId: this.ctx.state.tableId, otherTableId, userId },
                "requestUserLeaveBecauseJoiningAnotherTable failed",
              );
            }
          }
        }
      }

      if (this.ctx.dealer.hasPlayer(userId)) {
        const currentPlayer = this.ctx.state.playersById.get(userId);
        const shouldApplyJoinBuyInOverride =
          requestedBuyInCents != null &&
          this.ctx.state.street === "WAITING" &&
          currentPlayer?.stackCents === 0 &&
          currentPlayer?.status === "OUT";
        if (shouldApplyJoinBuyInOverride) {
          try {
            await room.processJoinBuyInForZeroStackSeatInternal(userId, requestedBuyInCents);
          } catch (err: any) {
            this.ctx.logger.warn(
              {
                roomId: room.roomId,
                tableId: this.ctx.state.tableId,
                userId,
                buyInCents: requestedBuyInCents,
                code: err instanceof PokerError ? err.code : "JOIN_BUYIN_FAILED",
                message: err?.message ?? String(err),
              },
              "POKER_JOIN_BUYIN_OVERRIDE_FAILED",
            );
            if (err instanceof PokerError) room.sendTableMessageInternal(client, "ERROR", { code: err.code, message: err.message });
            else room.sendTableMessageInternal(client, "ERROR", { code: "JOIN_BUYIN_FAILED", message: err?.message ?? String(err) });
            client.leave();
            return;
          }
        }

        this.session.rebindClientExclusive(userId, client);
        room.logRestoreBindOkInternal(userId, client.sessionId);
        await room.markReconnectedSafeInternal(userId);
        await room.clearSittingOutOnRestoreSafeInternal(userId);
        room.addTablePresenceInternal(client, userId, auth.username);
        if (room.persistentSeatsEnabledInternal) {
          const stackCents = room.getPlayerStackCentsInternal(userId);
          await TableSeatSessionService.touchConnected({
            tableId: this.ctx.state.tableId,
            userId,
            stackCentsSnapshot: stackCents,
            handIdSnapshot: this.ctx.state.handId || undefined,
          });
        }
        room.sendTableMessageInternal(client, "SESSION_RESTORED", { userId, deadlineTs: 0, joinMode: "RESTORE" });
        await room.emitSnapshotsToAllSafeInternal("RECONNECT");
        room.handleEmptyStateChangeInternal();
        return;
      }

      if (room.persistentSeatsEnabledInternal) {
        const persisted = await TableSeatSessionService.findRejoinableSession({
          tableId: this.ctx.state.tableId,
          userId,
        });
        if (persisted) {
          const shouldTreatPersistedAsNewJoin =
            requestedBuyInCents != null &&
            this.ctx.state.street === "WAITING" &&
            persisted.stackCentsSnapshot === 0 &&
            persisted.state === "SEATED_SITTING_OUT";
          if (shouldTreatPersistedAsNewJoin) {
            await TableSeatSessionService.markLeft({
              tableId: this.ctx.state.tableId,
              userId,
              reason: "JOIN_WITH_BUYIN_OVERRIDE",
              stackCentsSnapshot: persisted.stackCentsSnapshot,
              handIdSnapshot: this.ctx.state.handId || undefined,
            });
          } else {
            try {
              await this.ctx.dealer.restorePlayerFromSession(userId, auth.username, persisted.seat, persisted.stackCentsSnapshot);
              room.updateMetadataCountsInternal();
              this.session.rebindClientExclusive(userId, client);
              room.logRestoreBindOkInternal(userId, client.sessionId);
              await room.markReconnectedSafeInternal(userId);
              await room.clearSittingOutOnRestoreSafeInternal(userId);
              room.addTablePresenceInternal(client, userId, auth.username);
              await TableSeatSessionService.touchConnected({
                tableId: this.ctx.state.tableId,
                userId,
                stackCentsSnapshot: room.getPlayerStackCentsInternal(userId),
                handIdSnapshot: this.ctx.state.handId || undefined,
              });
              room.sendTableMessageInternal(client, "SESSION_RESTORED", { userId, deadlineTs: 0, joinMode: "RESTORE" });
              await room.emitSnapshotsToAllSafeInternal("RECONNECT");
              this.ctx.logger.info({ roomId: room.roomId, tableId: this.ctx.state.tableId, userId }, "POKER_JOIN_REBOUND_PERSISTED");
              room.handleEmptyStateChangeInternal();
              return;
            } catch (err: any) {
              this.ctx.logger.warn(
                {
                  roomId: room.roomId,
                  tableId: this.ctx.state.tableId,
                  userId,
                  code: err instanceof PokerError ? err.code : "RESTORE_FAILED",
                  message: err?.message ?? String(err),
                },
                "POKER_JOIN_REBOUND_PERSISTED_FAILED",
              );
              room.sendTableMessageInternal(client, "ERROR", {
                code: err instanceof PokerError ? err.code : "RESTORE_FAILED",
                message: err?.message ?? "Failed to restore persisted seat.",
              });
              client.leave();
              return;
            }
          }
        }
      }

      const parsedJoin = TableJoinOptionsSchema.safeParse(options ?? {});
      if (!parsedJoin.success) {
        const hasBuyInIssue = parsedJoin.error.issues.some((issue: ZodIssue) => issue.path[0] === "buyInCents");
        this.ctx.logger.warn(
          {
            roomId: room.roomId,
            tableId: this.ctx.state.tableId,
            userId,
            errors: parsedJoin.error.flatten(),
          },
          "POKER_JOIN_REJECTED_BAD_OPTIONS",
        );
        room.sendTableMessageInternal(client, "ERROR", {
          code: hasBuyInIssue ? "MISSING_BUY_IN_CENTS" : "BAD_JOIN_OPTIONS",
          message: hasBuyInIssue ? "buyInCents is required and must be a positive integer." : "Invalid join options.",
          details: parsedJoin.error.flatten(),
        });
        client.leave();
        return;
      }

      const name = auth.username;
      const buyInCents = parsedJoin.data.buyInCents;

      try {
        if (this.ctx.dealer.hasPlayer(userId)) {
          throw new PokerError("BAD_STATE", "User already seated at this table.");
        }

        this.session.rebindClientExclusive(userId, client);
        await this.ctx.dealer.addPlayer(userId, name, buyInCents);
        room.updateMetadataCountsInternal();

        if (room.persistentSeatsEnabledInternal) {
          const seat = room.findPlayerSeatInternal(userId);
          const stackCents = room.getPlayerStackCentsInternal(userId);
          if (seat !== null) {
            await TableSeatSessionService.upsertActiveSeat({
              tableId: this.ctx.state.tableId,
              userId,
              seat,
              stackCentsSnapshot: stackCents,
              buyInCents,
              handIdSnapshot: this.ctx.state.handId || undefined,
            });
          }
        }

        room.sendTableMessageInternal(client, "WELCOME", {
          roomId: room.roomId,
          playerId: userId,
          tableId: this.ctx.state.tableId,
          joinMode: "NEW",
        });
        room.addTablePresenceInternal(client, userId, auth.username);
        await room.emitSnapshotsToAllSafeInternal("JOIN");
        this.ctx.logger.info({ roomId: room.roomId, tableId: this.ctx.state.tableId, userId }, "POKER_JOIN_SUCCESS");
        room.handleEmptyStateChangeInternal();
      } catch (err: any) {
        this.ctx.logger.warn(
          {
            roomId: room.roomId,
            tableId: this.ctx.state.tableId,
            userId,
            code: err instanceof PokerError ? err.code : "JOIN_FAILED",
            message: err?.message ?? String(err),
          },
          "POKER_JOIN_FAILED",
        );
        if (err instanceof PokerError) room.sendTableMessageInternal(client, "ERROR", { code: err.code, message: err.message });
        else room.sendTableMessageInternal(client, "ERROR", { code: "JOIN_FAILED", message: err?.message ?? String(err) });
        client.leave();
      }
    });
  }
}

import { CloseCode, type Client } from "@colyseus/core";
import { TableSeatSessionService } from "../../engine/seats/TableSeatSessionService.js";
import type { PokerRoomSessionManager } from "./PokerRoomSessionManager.js";
import type { PokerRoomContext, PokerRoomLeaveServiceContract } from "./types/PokerRoomTypes.js";

export class PokerRoomLeaveService implements PokerRoomLeaveServiceContract {
  constructor(
    private readonly ctx: PokerRoomContext,
    private readonly session: PokerRoomSessionManager,
  ) {}

  async handleLeave(client: Client, code?: number): Promise<void> {
    const room = this.ctx.room;
    room.touchActivityInternal();
    room.handleEmptyStateChangeInternal();

    const leaveBindingEpoch = this.session.getBindingEpochForSession(client.sessionId);
    const userId = this.session.takeUserForSession(client.sessionId) ?? client.auth?.userId;

    if (!userId) return;

    const boundClient = this.session.getBoundClient(userId);
    if (boundClient && boundClient.sessionId !== client.sessionId) {
      this.ctx.logger.info(
        { roomId: room.roomId, tableId: this.ctx.state.tableId, userId, sessionId: client.sessionId, closeCode: code },
        "POKER_LEAVE_STALE_SESSION_IGNORED",
      );
      return;
    }

    if (!this.session.isBindingEpochCurrent(userId, leaveBindingEpoch)) {
      this.ctx.logger.info(
        {
          roomId: room.roomId,
          tableId: this.ctx.state.tableId,
          userId,
          sessionId: client.sessionId,
          leaveBindingEpoch,
          currentBindingEpoch: this.session.getBindingEpochForUser(userId),
          closeCode: code,
        },
        "POKER_LEAVE_STALE_EPOCH_IGNORED",
      );
      return;
    }

    this.ctx.dealer.unbindClient(userId);
    room.removeTablePresenceInternal(userId);
    room.updateMetadataCountsInternal();

    const consented = code === CloseCode.CONSENTED;
    this.ctx.logger.info(
      {
        roomId: room.roomId,
        tableId: this.ctx.state.tableId,
        userId,
        sessionId: client.sessionId,
        closeCode: code,
        consented,
        reconnectTimeoutMs: room.reconnectTimeoutMs,
      },
      "POKER_ON_LEAVE_PATH",
    );

    if (consented) {
      await this.ctx.dealer.handleConsentedLeave(userId);
      await room.maybeRemoveBotsIfNoHumansInternal();
      room.updateMetadataCountsInternal();
      if (room.persistentSeatsEnabledInternal) {
        await TableSeatSessionService.markLeft({
          tableId: this.ctx.state.tableId,
          userId,
          stackCentsSnapshot: 0,
          handIdSnapshot: this.ctx.state.handId || undefined,
        });
      }
      return;
    }

    if (code === room.leaveCodeSessionReplaced) {
      return;
    }

    const deadlineTs = Date.now() + room.reconnectTimeoutMs;
    this.ctx.logger.info(
      {
        roomId: room.roomId,
        tableId: this.ctx.state.tableId,
        userId,
        sessionId: client.sessionId,
        closeCode: code,
        deadlineTs,
      },
      "POKER_ON_LEAVE_DISCONNECT_WINDOW_STARTED",
    );
    await room.markDisconnectedSafeInternal(userId, deadlineTs);
    if (!this.session.isBindingEpochCurrent(userId, leaveBindingEpoch)) {
      this.ctx.logger.info(
        {
          roomId: room.roomId,
          tableId: this.ctx.state.tableId,
          userId,
          sessionId: client.sessionId,
          leaveBindingEpoch,
          currentBindingEpoch: this.session.getBindingEpochForUser(userId),
          closeCode: code,
        },
        "POKER_LEAVE_STALE_EPOCH_AFTER_DISCONNECT_IGNORED",
      );
      return;
    }
    room.updateMetadataCountsInternal();

    if (room.persistentSeatsEnabledInternal) {
      const stackCents = room.getPlayerStackCentsInternal(userId);
      await TableSeatSessionService.markSittingOut({
        tableId: this.ctx.state.tableId,
        userId,
        stackCentsSnapshot: stackCents,
        handIdSnapshot: this.ctx.state.handId || undefined,
      });
      if (!this.session.isBindingEpochCurrent(userId, leaveBindingEpoch)) {
        this.ctx.logger.info(
          {
            roomId: room.roomId,
            tableId: this.ctx.state.tableId,
            userId,
            sessionId: client.sessionId,
            leaveBindingEpoch,
            currentBindingEpoch: this.session.getBindingEpochForUser(userId),
            closeCode: code,
          },
          "POKER_LEAVE_STALE_EPOCH_AFTER_PERSIST_IGNORED",
        );
        return;
      }
    }

    try {
      const reconnected = await room.allowReconnection(client, Math.ceil(room.reconnectTimeoutMs / 1000));
      if (!this.session.isBindingEpochCurrent(userId, leaveBindingEpoch)) {
        this.ctx.logger.info(
          {
            roomId: room.roomId,
            tableId: this.ctx.state.tableId,
            userId,
            sessionId: client.sessionId,
            leaveBindingEpoch,
            currentBindingEpoch: this.session.getBindingEpochForUser(userId),
            closeCode: code,
          },
          "POKER_LEAVE_STALE_EPOCH_AFTER_ALLOW_RECONNECT_IGNORED",
        );
        try {
          reconnected.leave(room.leaveCodeSessionReplaced);
        } catch {}
        return;
      }

      if (room.isDeletingInternal) {
        room.sendTableMessageInternal(reconnected, "ERROR", { code: "TABLE_GONE", message: "Table no longer exists" });
        try {
          reconnected.leave();
        } catch {}
        return;
      }

      this.session.rebindClientExclusive(userId, reconnected);
      room.logRestoreBindOkInternal(userId, reconnected.sessionId);
      await room.markReconnectedSafeInternal(userId);
      await room.clearSittingOutOnRestoreSafeInternal(userId);
      room.addTablePresenceInternal(reconnected, userId);
      if (room.persistentSeatsEnabledInternal) {
        const stackCents = room.getPlayerStackCentsInternal(userId);
        await TableSeatSessionService.touchConnected({
          tableId: this.ctx.state.tableId,
          userId,
          stackCentsSnapshot: stackCents,
          handIdSnapshot: this.ctx.state.handId || undefined,
        });
      }
      room.sendTableMessageInternal(reconnected, "SESSION_RESTORED", { userId, deadlineTs: 0, joinMode: "RESTORE" });
      await room.emitSnapshotsToAllSafeInternal("RECONNECT");
      room.updateMetadataCountsInternal();
    } catch {
      if (room.persistentSeatsEnabledInternal) {
        room.updateMetadataCountsInternal();
        this.ctx.logger.info({ roomId: room.roomId, tableId: this.ctx.state.tableId, userId }, "POKER_RECONNECT_WINDOW_EXPIRED_SEAT_PRESERVED");
        return;
      }
      await room.markAbandonedSafeInternal(userId);
      await room.maybeRemoveBotsIfNoHumansInternal();
      room.updateMetadataCountsInternal();
    }
  }
}

import { sessionEvents } from "../../engine/auth/SessionEvents.js";
import type { PokerRoomContext, PokerRoomLifecycleContract } from "./types/PokerRoomTypes.js";

export class PokerRoomLifecycle implements PokerRoomLifecycleContract {
  constructor(private readonly ctx: PokerRoomContext) {}

  setup(options?: { cfg?: any }): void {
    this.ctx.startStallMonitor();
    this.ctx.updateCreateMetadata(options?.cfg);
    this.ctx.registerVoiceRelay();

    const onBan = async (payload: { userId: string }) => {
      await this.ctx.room.kickUserByAdmin(payload.userId, "BANNED");
    };
    sessionEvents.on("user.banned", onBan);
    this.ctx.setSessionEventUnbind(() => sessionEvents.off("user.banned", onBan));

    this.ctx.logger.info({ roomId: this.ctx.roomId, tableId: this.ctx.state.tableId }, "PokerRoom created");
    this.ctx.touchActivity();
    void this.ctx.bootstrapPersistentSeatRecovery();
  }

  dispose(): void {
    this.ctx.disposeRoom();
  }
}

import { nanoid } from "nanoid";
import {
  AddBotPayloadSchema,
  ChatPayloadSchema,
  RemoveBotPayloadSchema,
  TableInboundMessageSchema,
} from "@poker-champ/realtime-contract";
import { ActionPayloadSchema } from "@poker-champ/realtime-contract";
import { PokerError } from "../../engine/errors.js";
import { newBotId } from "../../engine/bots/botIds.js";
import { listEnabledBotSummaries, resolveBotSelectionForAdd } from "../../engine/bots/BotCatalog.js";
import { TableSeatSessionService } from "../../engine/seats/TableSeatSessionService.js";
import type { PokerRoomSessionManager } from "./PokerRoomSessionManager.js";
import type { PokerRoomContext, PokerRoomMessageRouterContract } from "./types/PokerRoomTypes.js";

export class PokerRoomMessageRouter implements PokerRoomMessageRouterContract {
  constructor(
    private readonly ctx: PokerRoomContext,
    private readonly session: PokerRoomSessionManager,
  ) {}

  registerAll(): void {
    const room = this.ctx.room;

    room.onMessage("ADD_BOT", async (client: any, message: unknown) => {
      const parsed = AddBotPayloadSchema.safeParse(message);
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: parsed.error.flatten() });
        return;
      }

      const userId = this.session.getUserIdForSession(client.sessionId);
      if (!userId) {
        room.sendTableMessageInternal(client, "ERROR", { code: "UNAUTHORIZED", message: "Must be seated to add a bot." });
        return;
      }
      if (!this.session.isActiveBoundClient(userId, client)) return;

      try {
        const resolved = resolveBotSelectionForAdd(parsed.data.botId);
        if (!resolved.ok) {
          const reasonMessage =
            resolved.reason === "NO_ENABLED_BOTS" ? "No enabled bots are available." : "Unknown or disabled botId.";
          room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: reasonMessage });
          return;
        }
        const runtimeBotId = newBotId();
        const botName = resolved.bot.name ?? parsed.data.name ?? "Bot";
        await this.ctx.dealer.addBot(runtimeBotId, botName, parsed.data.buyInCents, resolved.bot.id);
        room.updateMetadataCountsInternal();
      } catch (err: unknown) {
        const e = err as { code?: string; message?: string };
        room.sendTableMessageInternal(client, "ERROR", { code: e?.code ?? "ADD_BOT_FAILED", message: e?.message ?? String(err) });
      }
    });

    room.onMessage("LIST_BOTS", (client: any, message: unknown) => {
      const parsed = TableInboundMessageSchema.safeParse({ type: "LIST_BOTS", payload: message ?? {} });
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: parsed.error.flatten() });
        return;
      }
      room.sendTableMessageInternal(client, "BOTS_LIST", { bots: listEnabledBotSummaries() });
    });

    room.onMessage("REMOVE_BOT", async (client: any, message: unknown) => {
      const parsed = RemoveBotPayloadSchema.safeParse(message);
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: parsed.error.flatten() });
        return;
      }
      const userId = this.session.getUserIdForSession(client.sessionId);
      if (!userId) {
        room.sendTableMessageInternal(client, "ERROR", { code: "UNAUTHORIZED", message: "Must be seated to remove a bot." });
        return;
      }
      if (!this.session.isActiveBoundClient(userId, client)) return;
      const bot = this.ctx.state.playersById.get(parsed.data.botId);
      const canRemoveBetweenHands = this.ctx.state.street === "WAITING";
      const canRemoveDuringHand =
        bot?.kind === "BOT" &&
        (bot.status === "ABANDONED" || bot.status === "OUT" || bot.sittingOutUntilNextHand || bot.stackCents === 0);
      if (!canRemoveBetweenHands && !canRemoveDuringHand) {
        room.sendTableMessageInternal(client, "ERROR", {
          code: "REMOVE_BOT_NOT_ALLOWED",
          message: "Can only remove bots between hands, or during a hand if the bot is sitting out or has zero stack.",
        });
        return;
      }
      try {
        await this.ctx.dealer.removeBot(parsed.data.botId);
        room.updateMetadataCountsInternal();
      } catch (err: unknown) {
        const e = err as { code?: string; message?: string };
        room.sendTableMessageInternal(client, "ERROR", {
          code: e?.code ?? "REMOVE_BOT_FAILED",
          message: e?.message ?? String(err),
        });
      }
    });

    room.onMessage("CHAT", (client: any, message: unknown) => {
      if (room.isChatRateLimitedInternal(client.sessionId)) {
        room.sendTableMessageInternal(client, "ERROR", {
          code: "RATE_LIMITED",
          message: "Too many messages. Slow down.",
          retryAfterSeconds: 2,
        });
        return;
      }
      room.touchActivityInternal();
      const parsed = ChatPayloadSchema.safeParse(message);
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: "Invalid chat message." });
        return;
      }
      const userId = this.session.getUserIdForSession(client.sessionId);
      if (!userId) {
        room.sendTableMessageInternal(client, "ERROR", { code: "UNAUTHORIZED", message: "Must be in the room to chat." });
        return;
      }
      if (!this.session.isActiveBoundClient(userId, client)) return;
      const player = room.getPlayerByUserIdInternal(userId);
      if (!player || player.kind === "BOT") {
        room.sendTableMessageInternal(client, "ERROR", { code: "UNAUTHORIZED", message: "Must be seated to chat." });
        return;
      }
      const payload = {
        id: nanoid(),
        tableId: this.ctx.state.tableId,
        senderUserId: userId,
        senderName: player.name || `player_${userId.slice(0, 6)}`,
        text: parsed.data.text,
        createdAtTs: Date.now(),
      };
      room.clients.forEach((c: any) => room.sendTableMessageInternal(c, "CHAT_MESSAGE", payload));
    });

    room.onMessage("ACTION", async (client: any, message: unknown) => {
      if (room.isActionRateLimitedInternal(client.sessionId)) {
        room.sendTableMessageInternal(client, "ERROR", {
          code: "RATE_LIMITED",
          message: "Too many actions. Slow down.",
          retryAfterSeconds: 2,
        });
        return;
      }
      const envelope = TableInboundMessageSchema.safeParse({ type: "ACTION", payload: message });
      if (!envelope.success) {
        const missingActionId = envelope.error.issues.some((issue) => issue.path.join(".") === "payload.actionId");
        if (missingActionId) {
          room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: "actionId is required for idempotency." });
          return;
        }
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: envelope.error.flatten() });
        return;
      }

      const rawMessage = (message && typeof message === "object" ? message : {}) as Record<string, unknown>;
      const normalized = room.normalizeActionPayloadInternal(rawMessage);
      if (!normalized) {
        const topLevelActionId = rawMessage.actionId;
        const nestedActionId =
          rawMessage.payload &&
          typeof rawMessage.payload === "object" &&
          typeof (rawMessage.payload as Record<string, unknown>).actionId === "string"
            ? (rawMessage.payload as Record<string, unknown>).actionId
            : undefined;
        const hasActionId =
          (typeof topLevelActionId === "string" && topLevelActionId.length > 0) ||
          (typeof nestedActionId === "string" && nestedActionId.length > 0);
        if (!hasActionId) {
          room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: "actionId is required for idempotency." });
          return;
        }
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: "Invalid ACTION message format." });
        return;
      }

      const parsed = ActionPayloadSchema.safeParse(normalized.payload);
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: parsed.error.flatten() });
        return;
      }

      const userId = this.session.getUserIdForSession(client.sessionId);
      try {
        if (!userId) {
          this.ctx.logger.warn(
            { roomId: room.roomId, tableId: this.ctx.state.tableId, sessionId: client.sessionId },
            "ACTION_REJECTED reason=SESSION_NOT_BOUND",
          );
          throw new PokerError("BAD_STATE", "Session is not bound to a seated user.");
        }

        const expectedEpoch = this.session.getBindingEpochForUser(userId);
        const sessionEpoch = this.session.getBindingEpochForSession(client.sessionId);
        if (sessionEpoch !== expectedEpoch) {
          this.ctx.logger.warn(
            { roomId: room.roomId, tableId: this.ctx.state.tableId, userId, sessionId: client.sessionId, expectedEpoch, sessionEpoch },
            "ACTION_REJECTED reason=STALE_SESSION",
          );
          return;
        }
        if (!this.session.isActiveBoundClient(userId, client)) {
          this.ctx.logger.warn(
            { roomId: room.roomId, tableId: this.ctx.state.tableId, userId, sessionId: client.sessionId },
            "ACTION_REJECTED reason=INACTIVE_BOUND_CLIENT",
          );
          return;
        }

        room.touchActivityInternal();
        this.ctx.logger.info(
          { roomId: room.roomId, tableId: this.ctx.state.tableId, userId, action: parsed.data.action, amountCents: parsed.data.amountCents },
          "POKER_ACTION_ATTEMPT",
        );

        await this.ctx.dealer.handleAction(userId, parsed.data, normalized.actionId, client);
        room.setLastAcceptedActionInternal(userId, {
          action: parsed.data.action,
          amountCents: parsed.data.amountCents,
          actionId: normalized.actionId,
          atTs: Date.now(),
        });

        this.ctx.logger.info(
          { roomId: room.roomId, tableId: this.ctx.state.tableId, userId, action: parsed.data.action, amountCents: parsed.data.amountCents },
          "POKER_ACTION_ACCEPTED",
        );
      } catch (err: any) {
        const isBenignDuplicateRetry = (() => {
          if (!(err instanceof PokerError)) return false;
          if (err.code !== "NOT_YOUR_TURN" && err.code !== "HAND_NOT_STARTED") return false;
          const last = room.getLastAcceptedActionInternal(userId ?? "");
          if (!last) return false;
          if (last.actionId !== normalized.actionId) return false;
          if (last.action !== parsed.data.action) return false;
          if ((last.amountCents ?? undefined) !== (parsed.data.amountCents ?? undefined)) return false;
          return Date.now() - last.atTs <= 1200;
        })();
        if (isBenignDuplicateRetry) {
          this.ctx.logger.info(
            {
              roomId: room.roomId,
              tableId: this.ctx.state.tableId,
              sessionId: client.sessionId,
              userId,
              action: parsed.data.action,
              amountCents: parsed.data.amountCents,
            },
            "POKER_ACTION_DUPLICATE_RETRY_IGNORED",
          );
          return;
        }

        this.ctx.logger.warn(
          {
            roomId: room.roomId,
            tableId: this.ctx.state.tableId,
            sessionId: client.sessionId,
            code: err instanceof PokerError ? err.code : "ACTION_REJECTED",
            message: err?.message ?? String(err),
          },
          "POKER_ACTION_REJECTED",
        );
        if (err instanceof PokerError) {
          room.sendTableMessageInternal(client, "ERROR", { code: err.code, message: err.message, ...(err.meta ?? {}) });
        } else {
          room.sendTableMessageInternal(client, "ERROR", { code: "ACTION_REJECTED", message: err?.message ?? String(err) });
        }
      }
    });

    room.onMessage("SET_SITTING_OUT", async (client: any, message: unknown) => {
      const parsed = TableInboundMessageSchema.safeParse({ type: "SET_SITTING_OUT", payload: message });
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: parsed.error.flatten() });
        return;
      }
      if (parsed.data.type !== "SET_SITTING_OUT") {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: "Invalid sit-out payload." });
        return;
      }
      const userId = this.session.getUserIdForSession(client.sessionId);
      if (!userId) {
        room.sendTableMessageInternal(client, "ERROR", { code: "UNAUTHORIZED", message: "Session is not bound to a seated user." });
        return;
      }
      if (!this.session.isActiveBoundClient(userId, client)) return;
      try {
        await this.ctx.dealer.setPlayerSittingOut(userId, parsed.data.payload.sittingOut);
        room.updateMetadataCountsInternal();
      } catch (err: any) {
        if (err instanceof PokerError) {
          room.sendTableMessageInternal(client, "ERROR", { code: err.code, message: err.message, ...(err.meta ?? {}) });
          return;
        }
        room.sendTableMessageInternal(client, "ERROR", { code: "SIT_OUT_TOGGLE_FAILED", message: err?.message ?? String(err) });
      }
    });

    room.onMessage("REJOIN", async (client: any, message: unknown) => {
      const parsed = TableInboundMessageSchema.safeParse({ type: "REJOIN", payload: message });
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: parsed.error.flatten() });
        return;
      }
      if (parsed.data.type !== "REJOIN") {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: "Invalid rejoin payload." });
        return;
      }
      const userId = this.session.getUserIdForSession(client.sessionId);
      if (!userId) {
        room.sendTableMessageInternal(client, "ERROR", { code: "REJOIN_FAILED_NOT_SEATED", message: "Could not rejoin table. You are not seated." });
        return;
      }
      if (!this.session.isActiveBoundClient(userId, client)) return;
      if (room.isDeletingInternal) {
        room.sendTableMessageInternal(client, "ERROR", { code: "REJOIN_FAILED_TABLE_GONE", message: "Table no longer exists" });
        return;
      }
      if (!this.ctx.dealer.hasPlayer(userId)) {
        room.sendTableMessageInternal(client, "ERROR", { code: "REJOIN_FAILED_NOT_SEATED", message: "Could not rejoin table. You are not seated." });
        return;
      }
      if (room.getPlayerStackCentsInternal(userId) <= 0) {
        room.sendTableMessageInternal(client, "ERROR", { code: "REJOIN_FAILED_OUT_OF_CHIPS", message: "Could not rejoin table. You are out of chips." });
        return;
      }
      try {
        await this.ctx.dealer.setPlayerSittingOut(userId, false);
        room.updateMetadataCountsInternal();
      } catch (err: any) {
        this.ctx.logger.warn(
          {
            roomId: room.roomId,
            tableId: this.ctx.state.tableId,
            userId,
            code: err instanceof PokerError ? err.code : "REJOIN_FAILED_TEMPORARY",
            message: err?.message ?? String(err),
          },
          "POKER_REJOIN_FAILED",
        );
        room.sendTableMessageInternal(client, "ERROR", { code: "REJOIN_FAILED_TEMPORARY", message: "Could not rejoin table. Please retry." });
      }
    });

    room.onMessage("JOIN_TABLE", async (client: any, message: unknown) => {
      const parsed = TableInboundMessageSchema.safeParse({ type: "JOIN_TABLE", payload: message });
      if (!parsed.success) {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", details: parsed.error.flatten() });
        return;
      }
      if (parsed.data.type !== "JOIN_TABLE") {
        room.sendTableMessageInternal(client, "ERROR", { code: "BAD_MESSAGE", message: "Invalid join payload." });
        return;
      }
      const userId = this.session.getUserIdForSession(client.sessionId);
      if (!userId) {
        room.sendTableMessageInternal(client, "ERROR", { code: "UNAUTHORIZED", message: "Session is not bound to a user." });
        return;
      }
      if (!this.session.isActiveBoundClient(userId, client)) return;
      if (room.isDeletingInternal) {
        room.sendTableMessageInternal(client, "ERROR", { code: "TABLE_GONE", message: "Table no longer exists" });
        return;
      }
      if (this.ctx.dealer.hasPlayer(userId)) {
        room.sendTableMessageInternal(client, "ERROR", { code: "ALREADY_SEATED", message: "You are already seated." });
        return;
      }

      const buyInCents = parsed.data.payload.buyInCents;
      const username =
        typeof client.auth?.username === "string" && client.auth.username.trim().length > 0
          ? client.auth.username
          : `player_${userId.slice(0, 6)}`;

      try {
        await this.ctx.dealer.addPlayer(userId, username, buyInCents);
        room.updateMetadataCountsInternal();

        if (room.persistentSeatsEnabledInternal) {
          const seat = room.findPlayerSeatInternal(userId);
          const stackCents = room.getPlayerStackCentsInternal(userId);
          if (seat !== null) {
            await TableSeatSessionService.upsertActiveSeat({
              tableId: this.ctx.state.tableId,
              userId,
              seat,
              stackCentsSnapshot: stackCents,
              buyInCents,
              handIdSnapshot: this.ctx.state.handId || undefined,
            });
          }
        }

        room.sendTableMessageInternal(client, "WELCOME", {
          roomId: room.roomId,
          playerId: userId,
          tableId: this.ctx.state.tableId,
          joinMode: "NEW",
        });
        room.addTablePresenceInternal(client, userId, username);
        await this.ctx.dealer.emitSnapshotToUser(userId, "JOIN");
      } catch (err: any) {
        this.ctx.logger.warn(
          {
            roomId: room.roomId,
            tableId: this.ctx.state.tableId,
            userId,
            code: err instanceof PokerError ? err.code : "JOIN_FAILED",
            message: err?.message ?? String(err),
          },
          "POKER_JOIN_TABLE_FAILED",
        );
        if (err instanceof PokerError) {
          room.sendTableMessageInternal(client, "ERROR", { code: err.code, message: err.message });
        } else {
          room.sendTableMessageInternal(client, "ERROR", { code: "JOIN_FAILED", message: err?.message ?? String(err) });
        }
      }
    });
  }
}

import type { Client } from "@colyseus/core";
