import type { Room } from "@colyseus/core";
import { VOICE_SIGNAL_TYPE } from "../../voice/contracts/voice-signals.js";
import { parseVoiceSignalMessage } from "./voice-signal-schema.js";
import { getClientUserId } from "./voice-client-identity.js";
import { shouldAllowVoiceRelay } from "./voice-feature-flag.js";
import { createVoiceRateLimiter } from "./voice-rate-limit.js";
import { getMessageByteSize } from "./voice-size-guard.js";
import { logger } from "../../lib/logger.js";

/**
 * register -> voice relay
 * Adds a message handler to the PokerRoom to forward VOICE signals:
 * - validate
 * - rate-limit
 * - size limit
 * - targeted forward to recipient only
 *
 * This MUST stay lightweight for free Railway servers.
 */
export function registerVoiceRelay(room: Room) {
  const limiter = createVoiceRateLimiter();

  room.onMessage(VOICE_SIGNAL_TYPE, (client: any, raw: any) => {
    if (!shouldAllowVoiceRelay()) return;

    const size = getMessageByteSize(raw);
    if (size > 32_000) {
      logger.warn({ size }, "VOICE_SIGNAL dropped (too large)");
      return;
    }

    const userId = getClientUserId(client);
    if (!userId) return;

    if (!limiter.allow(client.sessionId)) {
      logger.warn({ sessionId: client.sessionId }, "VOICE_SIGNAL dropped (rate limited)");
      return;
    }

    const msg = parseVoiceSignalMessage(raw);
    if (!msg) return;

    // Basic anti-spoof: enforce fromUserId matches this client userId.
    if (msg.fromUserId !== userId) {
      logger.warn({ userId, fromUserId: msg.fromUserId }, "VOICE_SIGNAL dropped (spoof)");
      return;
    }

    if (msg.toUserId === msg.fromUserId) {
      logger.warn({ userId, toUserId: msg.toUserId }, "VOICE_SIGNAL dropped (self-loop)");
      return;
    }

    // Channel policy: default uses roomId as channel, but we keep it flexible.
    // In poker-champ, channelId should be tableId.
    const roomChannel = (room as any).state?.tableId ?? (room as any).roomId;
    if (msg.channelId !== roomChannel) {
      logger.warn({ roomChannel, msgChannel: msg.channelId }, "VOICE_SIGNAL dropped (wrong channel)");
      return;
    }

    // Targeted forward
    const recipient = room.clients.find((c: any) => getClientUserId(c) === msg.toUserId);
    if (!recipient) return;

    recipient.send(VOICE_SIGNAL_TYPE, msg);
  });
}

/**
 * get -> client userId
 * Update this function to match your auth wiring.
 *
 * Common patterns:
 * - client.auth?.userId
 * - client.userData?.userId
 * - client.userId
 */
export function getClientUserId(client: any): string | null {
  return (
    client?.auth?.userId ??
    client?.userData?.userId ??
    client?.userId ??
    null
  );
}

import { describe, expect, it, vi } from "vitest";
import { Dealer } from "../../engine/Dealer.js";
import { ActionOptionsService } from "../../engine/dealer/index.js";
import { PokerState } from "../../state/PokerState.js";
import { PlayerState } from "../../state/PlayerState.js";

type ScenarioPlayer = {
  id: string;
  seat: number;
  stackCents: number;
  committedCents: number;
  status: PlayerState["status"];
  cards?: [string, string];
};

function makePlayer(input: {
  id: string;
  seat: number;
  stackCents: number;
  status?: PlayerState["status"];
}): PlayerState {
  const p = new PlayerState();
  p.id = input.id;
  p.userId = input.id;
  p.kind = "HUMAN";
  p.name = input.id;
  p.seat = input.seat;
  p.status = input.status ?? "ACTIVE";
  p.stackCents = input.stackCents;
  p.roundBetCents = 0;
  p.committedCents = 0;
  p.needsAction = false;
  p.connected = true;
  p.disconnectDeadlineTs = 0;
  return p;
}

function baseState(tableId: string): PokerState {
  const state = new PokerState();
  state.tableId = tableId;
  state.maxSeats = 6;
  state.smallBlindCents = 50;
  state.bigBlindCents = 100;
  state.minBuyInCents = 200;
  state.maxBuyInCents = 200000;
  state.street = "WAITING";
  state.seats.push("", "", "", "", "", "");
  return state;
}

async function runShowdownMatrixScenario(input: {
  name: string;
  players: ScenarioPlayer[];
  board: [string, string, string, string, string];
  expectedPayoutByUserId: Record<string, number>;
}) {
  const state = baseState(`table_${input.name}`);
  state.street = "SHOWDOWN";
  state.handId = `hand_${input.name}`;
  state.handNumber = 1;
  state.dealerSeat = 0;
  state.sbSeat = 1;
  state.bbSeat = 2;
  state.toActSeat = 0;
  state.board.push(...input.board);

  let potCents = 0;
  for (const sp of input.players) {
    const player = makePlayer({
      id: sp.id,
      seat: sp.seat,
      stackCents: sp.stackCents,
      status: sp.status,
    });
    player.committedCents = sp.committedCents;
    player.roundBetCents = sp.committedCents;
    state.playersById.set(sp.id, player);
    state.seats[sp.seat] = sp.id;
    potCents += sp.committedCents;
  }
  state.potCents = potCents;
  state.initialChipMassCents = potCents;

  const paidByUserId = new Map<string, number>();
  const persistence = {
    enabled: false,
    handHistory: null,
    postBlind: async (args: { currentBalance: number; amountCents: number }) => args.currentBalance - args.amountCents,
    debitBet: async (args: { currentBalance: number; amountCents: number }) => args.currentBalance - args.amountCents,
    creditPayout: async (args: { userId: string; currentBalance: number; amountCents: number }) => {
      paidByUserId.set(args.userId, (paidByUserId.get(args.userId) ?? 0) + args.amountCents);
      return args.currentBalance + args.amountCents;
    },
    assertHandBalanced: async () => {},
  } as any;

  const dealer = new Dealer(state, persistence);
  (dealer as any).scheduleNextHand = () => {};
  const holeCardsByPlayerId = (dealer as any).holeCardsByPlayerId as Map<string, string[]>;
  for (const sp of input.players) {
    if (sp.cards) holeCardsByPlayerId.set(sp.id, [sp.cards[0], sp.cards[1]]);
  }

  await (dealer as any).finishHandShowdownWithSidePots();
  const handResult = (dealer as any).lastHandResult as
    | { reason: "SHOWDOWN" | "LAST_PLAYER"; payoutsByUserId: Record<string, number> }
    | undefined;

  expect(handResult?.reason).toBe("SHOWDOWN");
  expect(handResult?.payoutsByUserId).toEqual(input.expectedPayoutByUserId);
  expect(Object.fromEntries(paidByUserId)).toEqual(input.expectedPayoutByUserId);
}

