        }
      }

      throw new Error(`Did not reproduce known all-in invariant bug. Trace=${trace.join("|")}`);
    } finally {
      setTimeoutSpy.mockRestore();
    }
  }, 120_000);
});

import { describe, expect, it, vi } from "vitest";
import pokersolver from "pokersolver";
import type { ActionPayload } from "@poker-champ/realtime-contract";
import { Dealer } from "../../engine/Dealer.js";
import { ActionOptionsService } from "../../engine/dealer/index.js";
import { buildSidePots, splitPotCents } from "../../engine/rules/SidePotManager.js";
import { PokerState } from "../../state/PokerState.js";
import { PlayerState } from "../../state/PlayerState.js";

const { Hand } = pokersolver as {
  Hand: {
    solve(cards: string[]): unknown;
    winners(hands: unknown[]): unknown[];
  };
};

function mulberry32(seed: number): () => number {
  let t = seed >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let x = Math.imul(t ^ (t >>> 15), 1 | t);
    x ^= x + Math.imul(x ^ (x >>> 7), 61 | x);
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

function randomIntInclusive(rng: () => number, min: number, max: number): number {
  if (max <= min) return min;
  return Math.floor(rng() * (max - min + 1)) + min;
}

function makePlayer(id: string, seat: number, stackCents: number): PlayerState {
  const p = new PlayerState();
  p.id = id;
  p.userId = id;
  p.kind = "HUMAN";
  p.name = id;
  p.seat = seat;
  p.status = "ACTIVE";
  p.stackCents = stackCents;
  p.roundBetCents = 0;
  p.committedCents = 0;
  p.needsAction = false;
  p.connected = true;
  p.disconnectDeadlineTs = 0;
  return p;
}

function seatOrderLeftOfDealer(state: PokerState): string[] {
  const out: string[] = [];
  for (let i = 1; i <= state.seats.length; i++) {
    const seat = (state.dealerSeat + i) % state.seats.length;
    const id = state.seats[seat];
    if (!id) continue;
    const p = state.playersById.get(id);
    if (p && p.status !== "OUT") out.push(id);
  }
  return out;
}

function pickRandomWeightedAction(
  rng: () => number,
  options: ReturnType<ActionOptionsService["buildHeroActionOptions"]>,
): ActionPayload {
  if (!options) return { action: "FOLD" };

  if (options.canRaise && rng() < 0.34) {
    const min = options.minRaiseTo ?? options.maxRaiseTo ?? 1;
    const max = options.maxRaiseTo ?? min;
    return { action: "RAISE", amountCents: randomIntInclusive(rng, min, max) };
  }
  if (options.canBet && rng() < 0.30) {
    const min = options.minRaiseTo ?? options.maxRaiseTo ?? 1;
    const max = options.maxRaiseTo ?? min;
    return { action: "BET", amountCents: randomIntInclusive(rng, min, max) };
  }
  if (options.canFold && rng() < 0.18) return { action: "FOLD" };
  if (options.canCall) return { action: "CALL" };
  if (options.canCheck) return { action: "CHECK" };
  // Keep this 6-max oracle test deterministic/stable; all-in fuzzing is covered elsewhere.
  if (options.canAllIn && options.canCall) return { action: "CALL" };
  if (options.canFold) return { action: "FOLD" };
  return { action: "CHECK" };
}

describe("payout randomized 6-max accuracy", () => {
  it("matches precalculated payouts across randomized 6-player hands", async () => {
    const rng = mulberry32(602026);
    try {
      const state = new PokerState();
      state.tableId = "table_payout_fuzz_6max";
      state.maxSeats = 6;
      state.smallBlindCents = 50;
      state.bigBlindCents = 100;
      state.minBuyInCents = 200;
      state.maxBuyInCents = 200000;
      state.street = "WAITING";
      for (let i = 0; i < 6; i++) {
        const id = `u${i + 1}`;
        state.seats.push(id);
        state.playersById.set(id, makePlayer(id, i, randomIntInclusive(rng, 2500, 12000)));
      }

      const contributedByUserId = new Map<string, number>();
      const paidByUserId = new Map<string, number>();
      const persistence = {
        enabled: false,
        handHistory: null,
        postBlind: async (args: { userId: string; currentBalance: number; amountCents: number }) => {
          contributedByUserId.set(args.userId, (contributedByUserId.get(args.userId) ?? 0) + args.amountCents);
          return args.currentBalance - args.amountCents;
        },
        debitBet: async (args: { userId: string; currentBalance: number; amountCents: number }) => {
          contributedByUserId.set(args.userId, (contributedByUserId.get(args.userId) ?? 0) + args.amountCents);
          return args.currentBalance - args.amountCents;
        },
        creditPayout: async (args: { userId: string; currentBalance: number; amountCents: number }) => {
          paidByUserId.set(args.userId, (paidByUserId.get(args.userId) ?? 0) + args.amountCents);
          return args.currentBalance + args.amountCents;
        },
        assertHandBalanced: async () => {},
      } as any;

      const dealer = new Dealer(state, persistence);
      (dealer as any).scheduleNextHand = () => {};
      const optionsService = new ActionOptionsService();

      const handsToPlay = 6;
      let handsPlayed = 0;
      let showdownHands = 0;
      let raiseOrBetCount = 0;

      for (let handNo = 1; handNo <= handsToPlay; handNo++) {
        const beforeContrib = new Map(contributedByUserId);
        const beforePaid = new Map(paidByUserId);
        const beforeStacks = new Map<string, number>();
        for (const [id, p] of state.playersById.entries()) beforeStacks.set(id, p.stackCents);

        await (dealer as any).startHand();
        if (state.street === "WAITING" || !state.handId) break;
        handsPlayed += 1;
        const trace: string[] = [`hand=${handNo}`, `handId=${state.handId}`];

        let guard = 0;
        while (state.street !== "WAITING") {
          guard += 1;
          if (guard >= 800) throw new Error(`Infinite loop: ${trace.join("|")}`);

          const toActId = state.seats[state.toActSeat];
          if (!toActId) throw new Error(`Missing toActId: ${trace.join("|")}`);
          const options = optionsService.buildHeroActionOptions(state, toActId);
          expect(options, `missing options for ${toActId}, ${trace.join("|")}`).toBeTruthy();
          const action = pickRandomWeightedAction(rng, options);
          if (action.action === "BET" || action.action === "RAISE") raiseOrBetCount += 1;
          trace.push(`${toActId}:${action.action}${action.amountCents ? `:${action.amountCents}` : ""}`);
          await dealer.handleAction(toActId, action);
        }

        const handResult = (dealer as any).lastHandResult as
          | {
              reason: "LAST_PLAYER" | "SHOWDOWN";
              winnerId?: string;
              board?: string[];
              payoutsByUserId: Record<string, number>;
              showdownHoleCardsByUserId?: Record<string, [string, string]>;
            }
          | undefined;
        expect(handResult, `missing hand result ${trace.join("|")}`).toBeDefined();

        const handContribByUser = new Map<string, number>();
        const handPayoutByUser = new Map<string, number>();
        for (const [id] of state.playersById.entries()) {
          handContribByUser.set(id, (contributedByUserId.get(id) ?? 0) - (beforeContrib.get(id) ?? 0));
          handPayoutByUser.set(id, (paidByUserId.get(id) ?? 0) - (beforePaid.get(id) ?? 0));
        }
        const handContrib = [...handContribByUser.values()].reduce((a, b) => a + b, 0);
        const handPayout = [...handPayoutByUser.values()].reduce((a, b) => a + b, 0);
        expect(handPayout, `conservation mismatch ${trace.join("|")}`).toBe(handContrib);

        const expectedByUser = new Map<string, number>();
        if (handResult?.reason === "LAST_PLAYER") {
          const winnerId = handResult.winnerId;
          if (!winnerId) throw new Error(`Missing winnerId for LAST_PLAYER ${trace.join("|")}`);
          expectedByUser.set(winnerId, handContrib);
        } else {
          showdownHands += 1;
          const board = handResult?.board ?? [];
          if (board.length !== 5) throw new Error(`Invalid showdown board ${trace.join("|")}`);

          const eligibleIds = new Set<string>(Object.keys(handResult?.showdownHoleCardsByUserId ?? {}));
          const pseudoPlayers = [...state.playersById.keys()].map((id) => {
            const p = new PlayerState();
            p.id = id;
            p.committedCents = handContribByUser.get(id) ?? 0;
            p.status = eligibleIds.has(id) ? "ACTIVE" : "FOLDED";
            return p;
          });
          const pots = buildSidePots(
            pseudoPlayers,
            pseudoPlayers.filter((p) => p.status === "ACTIVE"),
          );
          const seatOrder = seatOrderLeftOfDealer(state);

          const solved = new Map<string, unknown>();
          for (const id of eligibleIds) {
            const hole = (handResult?.showdownHoleCardsByUserId ?? {})[id];
            if (!hole) continue;
            solved.set(id, Hand.solve([hole[0], hole[1], ...board]));
          }

          for (const pot of pots) {
            if (pot.eligiblePlayerIds.length === 0) continue;
            const contenders = pot.eligiblePlayerIds.filter((id) => solved.has(id));
            if (contenders.length === 0) continue;
            const winners = Hand.winners(contenders.map((id) => solved.get(id)!));
            const winnerIds = contenders.filter((id) => winners.includes(solved.get(id)!));
            const split = splitPotCents(pot.amountCents, winnerIds, seatOrder);
            for (const [id, amount] of split.entries()) {
              expectedByUser.set(id, (expectedByUser.get(id) ?? 0) + amount);
            }
          }

          const expectedSumBeforeReconcile = [...expectedByUser.values()].reduce((a, b) => a + b, 0);
          if (expectedSumBeforeReconcile < handContrib && eligibleIds.size > 0) {
            const remainder = handContrib - expectedSumBeforeReconcile;
            const seatOrderIndex = new Map<string, number>();
            seatOrder.forEach((id, idx) => seatOrderIndex.set(id, idx));
            const fallbackRecipientId = [...eligibleIds].sort((a, b) => {
              const byCommit = (handContribByUser.get(b) ?? 0) - (handContribByUser.get(a) ?? 0);
              if (byCommit !== 0) return byCommit;
              const ai = seatOrderIndex.get(a) ?? Number.MAX_SAFE_INTEGER;
              const bi = seatOrderIndex.get(b) ?? Number.MAX_SAFE_INTEGER;
              return ai - bi;
            })[0];
            if (fallbackRecipientId) {
              expectedByUser.set(fallbackRecipientId, (expectedByUser.get(fallbackRecipientId) ?? 0) + remainder);
            }
          }
        }

        const expectedSum = [...expectedByUser.values()].reduce((a, b) => a + b, 0);
        expect(expectedSum, `expected sum mismatch ${trace.join("|")}`).toBe(handContrib);

        for (const [id, player] of state.playersById.entries()) {
          const actual = handPayoutByUser.get(id) ?? 0;
          const expected = expectedByUser.get(id) ?? 0;
          expect(actual, `payout mismatch user=${id} ${trace.join("|")}`).toBe(expected);

          const expectedEndingStack = (beforeStacks.get(id) ?? 0) - (handContribByUser.get(id) ?? 0) + actual;
          expect(player.stackCents, `stack mismatch user=${id} ${trace.join("|")}`).toBe(expectedEndingStack);
          expect(player.stackCents, `negative stack user=${id} ${trace.join("|")}`).toBeGreaterThanOrEqual(0);
        }
      }

      expect(handsPlayed).toBeGreaterThan(1);
      expect(raiseOrBetCount).toBeGreaterThan(2);
      expect(showdownHands).toBeGreaterThanOrEqual(1);
    } finally {
      // no-op
    }
  }, 180_000);
});

import { describe, expect, it, vi } from "vitest";
import pokersolver from "pokersolver";
import type { ActionPayload } from "@poker-champ/realtime-contract";
import { Dealer } from "../../engine/Dealer.js";
import { ActionOptionsService } from "../../engine/dealer/index.js";
import { PokerState } from "../../state/PokerState.js";
import { PlayerState } from "../../state/PlayerState.js";

const { Hand } = pokersolver as {
  Hand: {
    solve(cards: string[]): unknown;
    winners(hands: unknown[]): unknown[];
  };
};

type WeightedProfile = {
  foldRate: number;
  raiseRate: number;
  allInRate: number;
};

function mulberry32(seed: number): () => number {
  let t = seed >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let x = Math.imul(t ^ (t >>> 15), 1 | t);
    x ^= x + Math.imul(x ^ (x >>> 7), 61 | x);
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

function randomIntInclusive(rng: () => number, min: number, max: number): number {
  if (max <= min) return min;
  return Math.floor(rng() * (max - min + 1)) + min;
}

function makePlayer(id: string, seat: number, stackCents: number): PlayerState {
  const p = new PlayerState();
  p.id = id;
  p.userId = id;
  p.kind = "HUMAN";
  p.name = id;
  p.seat = seat;
  p.status = "ACTIVE";
  p.stackCents = stackCents;
  p.roundBetCents = 0;
  p.committedCents = 0;
  p.needsAction = false;
  p.connected = true;
  p.disconnectDeadlineTs = 0;
  return p;
}

function getSeatOrderLeftOfDealer(state: PokerState): string[] {
  const order: string[] = [];
  for (let i = 1; i <= state.seats.length; i++) {
    const seat = (state.dealerSeat + i) % state.seats.length;
    const id = state.seats[seat];
    if (!id) continue;
    const player = state.playersById.get(id);
    if (player && player.status !== "OUT") order.push(id);
  }
  return order;
}

function splitTiePotWithOddChip(
  potCents: number,
  winnerIds: string[],
  seatOrderLeftOfDealer: string[],
): Map<string, number> {
  const payouts = new Map<string, number>();
  if (potCents <= 0 || winnerIds.length === 0) return payouts;

  const base = Math.floor(potCents / winnerIds.length);
  let remainder = potCents - base * winnerIds.length;
  for (const id of winnerIds) payouts.set(id, base);

  if (remainder > 0) {
    const winners = new Set(winnerIds);
    for (const id of seatOrderLeftOfDealer) {
      if (remainder <= 0) break;
      if (!winners.has(id)) continue;
      payouts.set(id, (payouts.get(id) ?? 0) + 1);
      remainder -= 1;
    }
  }

  return payouts;
}

function pickAction(
  rng: () => number,
  options: ReturnType<ActionOptionsService["buildHeroActionOptions"]>,
  profile: WeightedProfile,
): ActionPayload {
  if (!options) return { action: "FOLD" };

  if (options.canAllIn && rng() < profile.allInRate) {
    return { action: "ALL_IN" };
  }

  if (options.canRaise && rng() < profile.raiseRate) {
    const min = options.minRaiseTo ?? options.maxRaiseTo ?? 1;
    const max = options.maxRaiseTo ?? min;
    const raiseTo = randomIntInclusive(rng, min, max);
    return { action: "RAISE", amountCents: raiseTo };
  }

  if (options.canBet && rng() < profile.raiseRate) {
    const min = options.minRaiseTo ?? options.maxRaiseTo ?? 1;
    const max = options.maxRaiseTo ?? min;
    const betTo = randomIntInclusive(rng, min, max);
    return { action: "BET", amountCents: betTo };
  }

  if (options.canFold && rng() < profile.foldRate) return { action: "FOLD" };
  if (options.canCall) return { action: "CALL" };
  if (options.canCheck) return { action: "CHECK" };
  if (options.canAllIn) return { action: "ALL_IN" };
  if (options.canFold) return { action: "FOLD" };

  return { action: "CHECK" };
}

describe("payout randomized heads-up accuracy", () => {
  it("matches precalculated payouts across randomized full hands with raises/all-ins", async () => {
    const runs = 12;
    const profiles: WeightedProfile[] = [
      { foldRate: 0.08, raiseRate: 0.62, allInRate: 0.1 },
      { foldRate: 0.2, raiseRate: 0.45, allInRate: 0.2 },
      { foldRate: 0.05, raiseRate: 0.25, allInRate: 0.42 },
    ];

    let raiseCount = 0;
    let allInCount = 0;
    let showdownCount = 0;

    try {
      for (let seed = 1; seed <= runs; seed++) {
        const rng = mulberry32(seed);
        const profile = profiles[seed % profiles.length]!;

        const state = new PokerState();
        state.tableId = `table_payout_fuzz_${seed}`;
        state.maxSeats = 2;
        state.smallBlindCents = 50;
        state.bigBlindCents = 100;
        state.minBuyInCents = 200;
        state.maxBuyInCents = 100000;
        state.seats.push("u1", "u2");
        state.street = "WAITING";

        const stack1 = randomIntInclusive(rng, 200, 5000);
        const stack2 = randomIntInclusive(rng, 200, 5000);
        const p1 = makePlayer("u1", 0, stack1);
        const p2 = makePlayer("u2", 1, stack2);
        state.playersById.set("u1", p1);
        state.playersById.set("u2", p2);

        const openingStacks = new Map<string, number>([
          ["u1", stack1],
          ["u2", stack2],
        ]);

        const contributedByUserId = new Map<string, number>();
        const paidByUserId = new Map<string, number>();
        const trace: string[] = [];

        const persistence = {
          enabled: false,
          handHistory: null,
          postBlind: async (args: { userId: string; currentBalance: number; amountCents: number }) => {
            contributedByUserId.set(args.userId, (contributedByUserId.get(args.userId) ?? 0) + args.amountCents);
            trace.push(`${args.userId}:POST_BLIND:${args.amountCents}`);
            return args.currentBalance - args.amountCents;
          },
          debitBet: async (args: { userId: string; currentBalance: number; amountCents: number; action: string }) => {
            contributedByUserId.set(args.userId, (contributedByUserId.get(args.userId) ?? 0) + args.amountCents);
            trace.push(`${args.userId}:${args.action}:${args.amountCents}`);
            return args.currentBalance - args.amountCents;
          },
          creditPayout: async (args: { userId: string; currentBalance: number; amountCents: number }) => {
            paidByUserId.set(args.userId, (paidByUserId.get(args.userId) ?? 0) + args.amountCents);
            trace.push(`${args.userId}:PAYOUT:${args.amountCents}`);
            return args.currentBalance + args.amountCents;
          },
          assertHandBalanced: async () => {},
        } as any;

        const dealer = new Dealer(state, persistence);
        (dealer as any).scheduleNextHand = () => {};

        const optionsService = new ActionOptionsService();
        await (dealer as any).startHand();

        let guard = 0;
        while (state.street !== "WAITING" && guard < 300) {
          guard += 1;
          const toActId = state.seats[state.toActSeat];
          if (!toActId) break;

          const options = optionsService.buildHeroActionOptions(state, toActId);
          const action = pickAction(rng, options, profile);
          if (action.action === "RAISE" || action.action === "BET") raiseCount += 1;
          if (action.action === "ALL_IN") allInCount += 1;
          trace.push(`TURN:${toActId}:${action.action}${action.amountCents ? `:${action.amountCents}` : ""}`);

          await dealer.handleAction(toActId, action);
        }

        expect(guard, `seed=${seed} trace=${trace.join("|")}`).toBeLessThan(300);
        expect(state.street, `seed=${seed} trace=${trace.join("|")}`).toBe("WAITING");

        const handResult = (dealer as any).lastHandResult as
          | { reason: "LAST_PLAYER" | "SHOWDOWN"; payoutsByUserId: Record<string, number>; winnerId?: string; board: string[] }
          | undefined;
        expect(handResult, `seed=${seed} trace=${trace.join("|")}`).toBeDefined();

        const expectedPot = (contributedByUserId.get("u1") ?? 0) + (contributedByUserId.get("u2") ?? 0);
        const actualPaid = (paidByUserId.get("u1") ?? 0) + (paidByUserId.get("u2") ?? 0);
        expect(actualPaid, `seed=${seed} trace=${trace.join("|")}`).toBe(expectedPot);
        expect(state.potCents, `seed=${seed} trace=${trace.join("|")}`).toBe(expectedPot);

        const c1 = contributedByUserId.get("u1") ?? 0;
        const c2 = contributedByUserId.get("u2") ?? 0;
        const expectedPayout = new Map<string, number>();
        if (handResult?.reason === "LAST_PLAYER") {
          const winnerId = handResult.winnerId;
          if (!winnerId) throw new Error(`Missing winner in LAST_PLAYER seed=${seed}`);
          expectedPayout.set(winnerId, expectedPot);
        } else {
          showdownCount += 1;
          const board = handResult?.board ?? [];
          const h1 = (handResult as any)?.showdownHoleCardsByUserId?.u1 ?? [];
          const h2 = (handResult as any)?.showdownHoleCardsByUserId?.u2 ?? [];
          if (h1.length !== 2 || h2.length !== 2 || board.length !== 5) {
            throw new Error(`Invalid showdown cards seed=${seed} board=${board.join(",")} h1=${h1.join(",")} h2=${h2.join(",")}`);
          }

          const s1 = Hand.solve([...h1, ...board]);
          const s2 = Hand.solve([...h2, ...board]);
          const winners = Hand.winners([s1, s2]);
          const winnerIds: string[] = [];
          if (winners.includes(s1)) winnerIds.push("u1");
          if (winners.includes(s2)) winnerIds.push("u2");

          const contestedMainPot = Math.min(c1, c2) * 2;
          const sidePotUncontested = Math.abs(c1 - c2);
          if (sidePotUncontested > 0) {
            const sideWinnerId = c1 > c2 ? "u1" : "u2";
            expectedPayout.set(sideWinnerId, (expectedPayout.get(sideWinnerId) ?? 0) + sidePotUncontested);
          }

          const split = splitTiePotWithOddChip(contestedMainPot, winnerIds, getSeatOrderLeftOfDealer(state));
          for (const [id, amount] of split.entries()) {
            expectedPayout.set(id, (expectedPayout.get(id) ?? 0) + amount);
          }
        }

        const actualMap = new Map<string, number>([
          ["u1", paidByUserId.get("u1") ?? 0],
          ["u2", paidByUserId.get("u2") ?? 0],
        ]);
        const expectedMap = new Map<string, number>([
          ["u1", expectedPayout.get("u1") ?? 0],
          ["u2", expectedPayout.get("u2") ?? 0],
        ]);
        expect(
          Object.fromEntries(actualMap),
          `seed=${seed} profile=${JSON.stringify(profile)} reason=${handResult?.reason} c1=${c1} c2=${c2} expected=${JSON.stringify(Object.fromEntries(expectedMap))} trace=${trace.join("|")}`,
        ).toEqual(Object.fromEntries(expectedMap));

        for (const id of ["u1", "u2"]) {
          const player = state.playersById.get(id)!;
          const expectedEndingStack =
            (openingStacks.get(id) ?? 0) -
            (contributedByUserId.get(id) ?? 0) +
            (paidByUserId.get(id) ?? 0);
          expect(player.stackCents, `seed=${seed} user=${id} trace=${trace.join("|")}`).toBe(expectedEndingStack);
          expect(player.stackCents, `seed=${seed} user=${id} trace=${trace.join("|")}`).toBeGreaterThanOrEqual(0);
        }
      }
    } finally {
      // no-op
    }

    expect(raiseCount).toBeGreaterThan(4);
    expect(allInCount).toBeGreaterThan(2);
    expect(showdownCount).toBeGreaterThan(2);
  }, 90_000);
});

import { afterEach, describe, expect, it, vi } from "vitest";
import { PokerRoom } from "../../rooms/PokerRoom.js";
import type { DealerDiagnosticEvent, DealerDiagnosticType } from "../../engine/Dealer.js";
import { CashierService } from "../../engine/economy/CashierService.js";
import { TableSeatSessionService } from "../../engine/seats/TableSeatSessionService.js";
import type { TableSnapshotPayload } from "@poker-champ/realtime-contract";
import { getActionableToActSeatFindingFromSnapshot, getSnapshotMoneyFindings } from "../../engine/invariants/churnInvariantContract.js";

vi.setConfig({ testTimeout: 30000 });

type FakeClient = {
  sessionId: string;
  leave: () => void;
  send: (type: string, payload: unknown) => void;
  sentByType: Record<string, unknown[]>;
  latestSnapshot: TableSnapshotPayload | null;
};

const DIAGNOSTIC_DENYLIST: DealerDiagnosticType[] = [
  "QUEUED_AUTO_ACTION_FAILED",
  "QUEUE_RECOVERY_AFTER_FAILURE",
  "ACTION_FAILED",
];

function makeClient(sessionId: string): FakeClient {
  const sentByType: Record<string, unknown[]> = {};
  const client: FakeClient = {
    sessionId,
    sentByType,
    latestSnapshot: null,
    leave: () => {},
    send: (type: string, payload: unknown) => {
      if (!sentByType[type]) sentByType[type] = [];
      sentByType[type].push(payload);
      if (type === "TABLE_SNAPSHOT") client.latestSnapshot = payload as TableSnapshotPayload;
    },
  };
  return client;
}

function delay(ms: number) {
  return new Promise<void>((resolve) => setTimeout(resolve, ms));
}

async function waitFor(condition: () => boolean, timeoutMs: number, label: string) {
  const started = Date.now();
  while (!condition()) {
    if (Date.now() - started > timeoutMs) {
      throw new Error(`Timed out waiting for: ${label}`);
    }
    await delay(30);
  }
}

function pickLegalAction(snapshot: TableSnapshotPayload): { action: "FOLD" | "CHECK" | "CALL" | "ALL_IN" } {
  const opts = snapshot.hero.actionOptions;
  if (!opts) return { action: "FOLD" };
  if (opts.canCheck) return { action: "CHECK" };
  if (opts.canCall) return { action: "CALL" };
  if (opts.canFold) return { action: "FOLD" };
  if (opts.canAllIn) return { action: "ALL_IN" };
  return { action: "FOLD" };
}

function sumPayouts(result: TableSnapshotPayload["lastHandResult"] | undefined): number {
  return Object.values(result?.payoutsByUserId ?? {}).reduce((sum, value) => sum + value, 0);
}

function assertSnapshotChurnInvariants(snapshot: TableSnapshotPayload): void {
  expect(getSnapshotMoneyFindings(snapshot)).toEqual([]);
  expect(getActionableToActSeatFindingFromSnapshot(snapshot)).toBeNull();
  if (snapshot.lastHandResult) {
    expect(sumPayouts(snapshot.lastHandResult)).toBe(snapshot.lastHandResult.potCents);
  }
}

async function settleHandToWaiting(
  room: any,
  clientsByUserId: Record<string, FakeClient | undefined>,
  maxSteps = 36,
): Promise<void> {
  for (let i = 0; i < maxSteps && room.state.street !== "WAITING"; i += 1) {
    const toActUserId = String(room.state.seats?.[room.state.toActSeat] ?? "");
    const actorClient = clientsByUserId[toActUserId];
    const actorSnapshot = actorClient?.latestSnapshot;
    if (actorClient && actorSnapshot && actorSnapshot.hand?.handId === room.state.handId && !actorSnapshot.lastHandResult?.handId) {
      const action = { ...pickLegalAction(actorSnapshot), actionId: `settle-${i}-${Date.now()}` };
      room.onMessageEvents.emit("ACTION", actorClient as any, action);
    }
    await delay(120);
  }
  await waitFor(() => room.state.street === "WAITING", 10000, "hand settles to WAITING");
}

